/** Registry slug + demo title -> precomputed JavaScript variant. */
export const demoJs: Record<string, string> = {"button::Variants":"import { Button } from \"pollen-ui\";\nexport default function Page() {\n    return (<div className=\"flex flex-wrap gap-2.5\">\n      <Button>Primary</Button>\n      <Button variant=\"accent\">Accent</Button>\n      <Button variant=\"secondary\">Secondary</Button>\n      <Button variant=\"outline\">Outline</Button>\n      <Button variant=\"ghost\">Ghost</Button>\n      <Button variant=\"link\">Learn more</Button>\n      <Button variant=\"destructive\">Delete</Button>\n    </div>);\n}\n","button::Sizes":"import { Button, IconSettings } from \"pollen-ui\";\nexport default function Page() {\n    return (<div className=\"flex flex-wrap gap-2.5\">\n      <Button size=\"sm\">Small</Button>\n      <Button size=\"md\">Medium</Button>\n      <Button size=\"lg\">Large</Button>\n      <Button size=\"icon\" variant=\"outline\" aria-label=\"Settings\">\n        <IconSettings className=\"h-4 w-4\"/>\n      </Button>\n    </div>);\n}\n","button::Loading and disabled":"<Button loading loadingText=\"Deploying\">Deploy</Button>;\n<Button variant=\"secondary\" disabled>Disabled</Button>;\n","button::Icons":"<Button leftIcon={<IconDeploy />}>Deploy project</Button>;\n<Button variant=\"secondary\" rightIcon={<IconArrowRight />}>Continue</Button>;\n<Button variant=\"outline\" size=\"sm\" leftIcon={<IconSettings />}>Settings</Button>;\n","badge::Variants":"import { Badge } from \"pollen-ui\";\n<div className=\"flex flex-wrap gap-2\">\n  <Badge>Stable</Badge>\n  <Badge variant=\"solid\">v2.0</Badge>\n  <Badge variant=\"accent\">New</Badge>\n  <Badge variant=\"success\">Ready</Badge>\n  <Badge variant=\"warning\">Pending</Badge>\n  <Badge variant=\"danger\">Deprecated</Badge>\n</div>;\n","badge::Status dots":"<Badge dot variant=\"success\">Operational</Badge>;\n<Badge dot variant=\"warning\">Degraded</Badge>;\n<Badge dot variant=\"danger\">Outage</Badge>;\n","badge::Counters":"<Badge count={3}/>;\n<Badge count={12}/>;\n<Badge count={128}/>;\n{ /* renders 99+ */ }\n","badge::Dismissible":"<Badge variant=\"accent\" dismissible>Pro plan</Badge>;\n<Badge dismissible onDismiss={() => { }}/>;\n","badge::Sizes":"<Badge size=\"sm\" dot variant=\"accent\">Small</Badge>;\n<Badge size=\"md\" dot variant=\"accent\">Medium</Badge>;\n<Badge size=\"lg\" dot variant=\"accent\">Large</Badge>;\n","input::Basic":"import { Input, Label } from \"pollen-ui\";\n<div className=\"space-y-2\">\n  <Label htmlFor=\"email\">Email</Label>\n  <Input id=\"email\" type=\"email\" placeholder=\"you@example.com\"/>\n</div>;\n","input::Icon and error state":"import { Input, IconSearch, IconMail } from \"pollen-ui\";\n<Input icon={<IconSearch />} placeholder=\"Search projects\"/>;\n<Input icon={<IconMail />} invalid defaultValue=\"not-an-email\"/>;\n<p className=\"text-xs text-danger-ink\">Enter a valid email address.</p>;\n","input::Success state":"<Input valid successText=\"Address verified.\" label=\"Email\"/>;\n","input::Clearable and loading":"import { Input, IconSearch } from \"pollen-ui\";\n<Input clearable defaultValue=\"pollen-web\"/>;\n<Input icon={<IconSearch />} clearable loading placeholder=\"Search and wait\"/>;\n","input::Sizes":"<Input size=\"sm\" placeholder=\"Small, for dense toolbars\"/>;\n<Input size=\"md\" placeholder=\"Medium, the default\"/>;\n<Input size=\"lg\" placeholder=\"Large, for hero forms\"/>;\n","input::Variants":"<Input variant=\"fill\" placeholder=\"Fill, the default\"/>;\n<Input variant=\"outline\" placeholder=\"Outline, for forms on white\"/>;\n<Input variant=\"underline\" placeholder=\"Underline, for inline editing\"/>;\n<Input variant=\"ghost\" placeholder=\"Ghost, for toolbars\"/>;\n","input::Pill shape":"import { Input, IconSearch } from \"pollen-ui\";\n<Input shape=\"pill\" icon={<IconSearch />} placeholder=\"Search components\"/>;\n","input::Password, prefix, count":"import { Input } from \"pollen-ui\";\n<Input type=\"password\" passwordToggle label=\"Password\"/>;\n<Input prefix=\"https://\" label=\"Custom domain\" helperText=\"Verify with a DNS record.\"/>;\n<Input charCount maxLength={48} label=\"Tagline\"/>;\n","textarea::Basic":"import { Textarea, Label } from \"pollen-ui\";\n<div className=\"space-y-2\">\n  <Label htmlFor=\"bio\">Project description</Label>\n  <Textarea id=\"bio\" placeholder=\"A short summary of what you are building\"/>\n</div>;\n","textarea::Variants":"<Textarea variant=\"fill\" placeholder=\"Fill, the default\"/>;\n<Textarea variant=\"outline\" placeholder=\"Outline, for forms on white\"/>;\n<Textarea variant=\"underline\" placeholder=\"Underline, for inline editing\"/>;\n<Textarea variant=\"ghost\" placeholder=\"Ghost, for quiet surfaces\"/>;\n","textarea::Label, count and states":"<Textarea label=\"Release notes\" charCount maxLength={120}/>;\n<Textarea label=\"Summary\" invalid errorText=\"Keep the summary under 140 characters.\"/>;\n","textarea::Auto grow":"<Textarea autoGrow label=\"Notes\" placeholder=\"Type — the field grows with you\"/>;\n","label::With helper text":"import { Input, Label } from \"pollen-ui\";\n<div className=\"space-y-2\">\n  <Label htmlFor=\"key\">API key</Label>\n  <Input id=\"key\" placeholder=\"sk_live_...\" className=\"font-mono\"/>\n  <p className=\"text-xs text-muted-foreground\">\n    Keep it secret. Rotate it any time from settings.\n  </p>\n</div>;\n","select::Basic":"import { Select } from \"pollen-ui\";\n<Select defaultValue=\"nextjs\" options={[\n        { value: \"nextjs\", label: \"Next.js\", description: \"React framework with App Router\" },\n        { value: \"astro\", label: \"Astro\", description: \"Content-driven websites\" },\n        { value: \"sveltekit\", label: \"SvelteKit\", description: \"Svelte applications\" },\n        { value: \"remix\", label: \"Remix\", disabled: true },\n    ]}/>;\n","checkbox::States":"import { Checkbox } from \"pollen-ui\";\n<Checkbox defaultChecked>Email digests</Checkbox>;\n<Checkbox>Weekly summary</Checkbox>;\n<Checkbox indeterminate>Notifications (partial)</Checkbox>;\n<Checkbox disabled>Enterprise feature</Checkbox>;\n","checkbox::Card mode":"<Checkbox card defaultChecked description=\"Every push, pr, and deployment event\">\n  All activity\n</Checkbox>;\n<Checkbox card description=\"Only mentions, reviews and requests\">\n  Important only\n</Checkbox>;\n","radio-group::Basic":"import { Radio, RadioGroup } from \"pollen-ui\";\n<RadioGroup defaultValue=\"pro\">\n  <Radio value=\"hobby\">Hobby, for side projects</Radio>\n  <Radio value=\"pro\">Pro, for growing teams</Radio>\n  <Radio value=\"enterprise\">Enterprise, with SSO and SLA</Radio>\n</RadioGroup>;\n","switch::Settings rows":"import { Switch } from \"pollen-ui\";\n<div className=\"flex items-center justify-between p-3.5\">\n  <span className=\"text-sm font-medium\">Public profile</span>\n  <Switch defaultChecked/>\n</div>;\n","switch::Sizes, icons and loading":"<Switch size=\"sm\" defaultChecked/>;\n<Switch size=\"lg\" defaultChecked/>;\n<Switch defaultChecked onIcon={<IconCheck />} offIcon={<IconMinus />}/>;\n<Switch loading defaultChecked/>;\n","slider::Basic":"import { Slider } from \"pollen-ui\";\nconst [volume, setVolume] = useState(40);\n<div className=\"w-full max-w-[260px]\">\n  <div className=\"mb-3 flex justify-between text-sm\">\n    <span className=\"font-medium\">Volume</span>\n    <span className=\"text-muted-foreground\">{volume}%</span>\n  </div>\n  <Slider value={volume} onValueChange={setVolume} min={0} max={100} step={1} aria-label=\"Volume\"/>\n</div>;\n","slider::Range with marks":"<Slider defaultValue={[24, 72]} minStepsBetweenThumbs={5} marks={[\n        { value: 0, label: \"0\" },\n        { value: 50, label: \"50\" },\n        { value: 100, label: \"100\" },\n    ]}/>;\n","slider::Formatted bubble":"<Slider defaultValue={46} tooltipAlways formatValue={(v) => }/>;\n`$\\${v},000\\`}\n  aria-label=\"Salary\"\n/>\n\n<Slider\n  orientation=\"vertical\"\n  defaultValue={62}\n  formatValue={(v) => \\`\\${v}°\\`}\n  aria-label=\"Temperature\"\n/>;\n","toggle-group::Single selection":"import { ToggleGroup, ToggleGroupItem } from \"pollen-ui\";\nexport default function Page() {\n    return (<ToggleGroup type=\"single\" defaultValue=\"dense\">\n      <ToggleGroupItem value=\"cozy\">Cozy</ToggleGroupItem>\n      <ToggleGroupItem value=\"dense\">Dense</ToggleGroupItem>\n      <ToggleGroupItem value=\"list\">List</ToggleGroupItem>\n    </ToggleGroup>);\n}\n","toggle-group::Multiple selection":"<ToggleGroup type=\"multiple\" defaultValue={[\"bold\", \"italic\"]}>\n  <ToggleGroupItem value=\"bold\">Bold</ToggleGroupItem>\n  <ToggleGroupItem value=\"italic\">Italic</ToggleGroupItem>\n</ToggleGroup>;\n","otp-input::Six digits":"import { useState } from \"react\";\nimport { OTPInput } from \"pollen-ui\";\nexport default function Page() {\n    const [code, setCode] = useState(\"\");\n    return (<OTPInput length={6} value={code} onChange={setCode} onComplete={(value) => console.log(value)} aria-label=\"Verification code\"/>);\n}\n","otp-input::Alphanumeric, invalid state":"<OTPInput length={4} alphanumeric defaultValue=\"7X2K\"/>;\n<OTPInput length={6} defaultValue=\"12\" invalid/>;\n","knob::Basic":"import { useState } from \"react\";\nimport { Knob } from \"pollen-ui\";\nconst [level, setLevel] = useState(64);\n<Knob value={level} onValueChange={setLevel} min={0} max={100} label=\"Level\"/>;\n","knob::Sweeps and tones":"// The classic 270 degree dial.\n<Knob defaultValue={30} tone=\"accent\" label=\"Gain\" size={84}/>;\n<Knob defaultValue={0.5} min={0} max={1} step={0.05} precision={2} startAngle={-90} endAngle={90} tone=\"success\" label=\"Opacity\" size={84}/>;\n<Knob defaultValue={80} min={0} max={120} tone=\"danger\" label=\"Threshold\" showValue={false}/>;\n","stepper::Basic":"import { useState } from \"react\";\nimport { Stepper } from \"pollen-ui\";\nconst [seats, setSeats] = useState(3);\n<Stepper value={seats} onValueChange={setSeats} min={1} max={12} aria-label=\"Seats\"/>;\n<Stepper defaultValue={0} min={0} max={99} size=\"sm\" aria-label=\"Guest passes\"/>;\n","modal::Basic":"import { Button, Modal, ModalClose, ModalContent, ModalDescription, ModalFooter, ModalTitle, } from \"pollen-ui\";\nconst [open, setOpen] = useState(false);\n<Button variant=\"outline\" onClick={() => setOpen(true)}>\n  Open dialog\n</Button>;\n<Modal open={open} onOpenChange={setOpen}>\n  <ModalContent>\n    <ModalTitle>Move project</ModalTitle>\n    <ModalDescription>\n      Choose a workspace for pollen-web. Members keep their access.\n    </ModalDescription>\n    <ModalClose />\n    <ModalFooter>\n      <Button variant=\"ghost\" onClick={() => setOpen(false)}>Cancel</Button>\n      <Button onClick={() => setOpen(false)}>Move project</Button>\n    </ModalFooter>\n  </ModalContent>\n</Modal>;\n","modal::Sizes":"import { Button, Modal, ModalContent, ModalDescription, ModalFooter, ModalTitle } from \"pollen-ui\";\nconst [size, setSize] = useState(null);\n<Button onClick={() => setSize(\"lg\")}>Invite people</Button>;\n<Modal open={size !== null} onOpenChange={(o) => !o && setSize(null)} size={size ?? \"md\"}>\n  <ModalContent>\n    <ModalTitle>Invite to workspace</ModalTitle>\n    <ModalDescription>\n      They will get an email with a link to join pollen-web.\n    </ModalDescription>\n    <ModalFooter>\n      <Button variant=\"ghost\" onClick={() => setSize(null)}>Cancel</Button>\n      <Button onClick={() => setSize(null)}>Send invite</Button>\n    </ModalFooter>\n  </ModalContent>\n</Modal>;\n","drawer::From the right":"import { Drawer, DrawerBody, DrawerClose, DrawerHeader, DrawerTitle, } from \"pollen-ui\";\nconst [open, setOpen] = useState(false);\n<Drawer open={open} onOpenChange={setOpen} side=\"right\">\n  <DrawerHeader>\n    <DrawerTitle>Filters</DrawerTitle>\n    <DrawerClose onOpenChange={setOpen}/>\n  </DrawerHeader>\n  <DrawerBody>{/* your content */}</DrawerBody>\n</Drawer>;\n","tooltip::Placement":"import { Button, Tooltip, IconCopy } from \"pollen-ui\";\n<Tooltip content=\"Copy to clipboard\">\n  <Button variant=\"outline\" aria-label=\"Copy\">\n    <IconCopy className=\"h-4 w-4\"/>\n  </Button>\n</Tooltip>;\n<Tooltip content=\"Invite your team\" side=\"bottom\">\n  <Button variant=\"outline\">Invite</Button>\n</Tooltip>;\n","dropdown-menu::Project actions":"import { Button, DropdownMenu, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, IconPencil, IconCopy, IconTrash, } from \"pollen-ui\";\n<DropdownMenu trigger={<Button variant=\"outline\">Actions</Button>}>\n  <DropdownMenuLabel>Project</DropdownMenuLabel>\n  <DropdownMenuItem icon={<IconPencil />} shortcut={[\"⌘\", \"E\"]}>Rename</DropdownMenuItem>\n  <DropdownMenuItem icon={<IconCopy />} shortcut={[\"⌘\", \"D\"]}>Duplicate</DropdownMenuItem>\n  <DropdownMenuSeparator />\n  <DropdownMenuItem icon={<IconTrash />} destructive>Delete</DropdownMenuItem>\n</DropdownMenu>;\n","dropdown-menu::Checkable items":"import { Button, DropdownMenu, DropdownMenuItem, DropdownMenuLabel, } from \"pollen-ui\";\nimport { useState } from \"react\";\nexport default function Demo() {\n    const [density, setDensity] = useState(\"Comfortable\");\n    return (<DropdownMenu trigger={<Button variant=\"outline\">Density: {density}</Button>}>\n      <DropdownMenuLabel>Row density</DropdownMenuLabel>\n      {[\"Comfortable\", \"Compact\"].map((option) => (<DropdownMenuItem key={option} selected={density === option} onSelect={() => setDensity(option)}>\n          {option}\n        </DropdownMenuItem>))}\n    </DropdownMenu>);\n}\n","command::Basic":"import { Command } from \"pollen-ui\";\nimport { useState } from \"react\";\nexport default function Demo() {\n    const [open, setOpen] = useState(false);\n    const groups = [\n        {\n            heading: \"Suggested\",\n            items: [\n                { label: \"Copy link\", shortcut: [\"⌘\", \"C\"] },\n                { label: \"Open docs\", shortcut: [\"⌘\", \"D\"] },\n                { label: \"Invite people\", shortcut: [\"⌘\", \"I\"] },\n            ],\n        },\n        {\n            heading: \"Project\",\n            items: [\n                { label: \"View deployments\" },\n                { label: \"Open logs\" },\n                { label: \"Archive project\" },\n            ],\n        },\n    ];\n    return (<Command open={open} onOpenChange={setOpen} groups={groups}/>);\n}\n","toast::Variants":"import { useEffect } from \"react\";\nimport { Toaster, toast } from \"pollen-ui\";\n// Mount one Toaster near the root of your app, then call\n// toast() from anywhere.\nexport default function Demo() {\n    useEffect(() => {\n        toast.success(\"Settings saved\", {\n            description: \"Your changes are live for your team.\",\n        });\n        const timer = window.setTimeout(() => {\n            toast(\"Project deleted\", {\n                description: \"You can undo this for the next 30 days.\",\n                action: { label: \"Undo\", onClick: () => toast.success(\"Restored\") },\n            });\n        }, 700);\n        return () => window.clearTimeout(timer);\n    }, []);\n    return <Toaster />;\n}\n","toast::Controlled pile":"import { ToastPileProvider, useToastPile, Button } from \"pollen-ui\";\n// Scope the pile to the part of the app that owns it.\n// ToastPileProvider renders the pile itself.\nfunction Composer() {\n    const { pile } = useToastPile();\n    return (<Button onClick={() => pile({\n            title: \"Report queued\",\n            description: \"We will email you when it is ready.\",\n            duration: 6000,\n        })}>\n      Queue report\n    </Button>);\n}\nexport default function Demo() {\n    return (<ToastPileProvider>\n      <Composer />\n    </ToastPileProvider>);\n}\n","popover::Invite form":"import { Button, Input, Label, Popover } from \"pollen-ui\";\n<Popover trigger={<Button variant=\"outline\">Invite</Button>}>\n  <div className=\"w-64\">\n    <Label htmlFor=\"email\">Email address</Label>\n    <Input id=\"email\" placeholder=\"mira@pollen.dev\" className=\"mt-2\"/>\n    <Button size=\"sm\" className=\"mt-4 w-full\">Send invite</Button>\n  </div>\n</Popover>;\n","popover::Sides":"<Popover side=\"top\" trigger={<Button>Top</Button>}>…</Popover>;\n<Popover side=\"bottom\" trigger={<Button>Bottom</Button>}>…</Popover>;\n<Popover side=\"left\" trigger={<Button>Left</Button>}>…</Popover>;\n<Popover side=\"right\" trigger={<Button>Right</Button>}>…</Popover>;\n","context-menu::File actions":"import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuLabel, ContextMenuSeparator, ContextMenuTrigger, Button, IconPencil, IconTrash, } from \"pollen-ui\";\n<ContextMenu>\n  <ContextMenuTrigger>\n    <Button variant=\"outline\">Right click anywhere in here</Button>\n  </ContextMenuTrigger>\n  <ContextMenuContent>\n    <ContextMenuLabel>File</ContextMenuLabel>\n    <ContextMenuItem icon={<IconPencil />} shortcut={[\"E\"]}>Rename</ContextMenuItem>\n    <ContextMenuSeparator />\n    <ContextMenuItem icon={<IconTrash />} destructive>Delete file</ContextMenuItem>\n  </ContextMenuContent>\n</ContextMenu>;\n","combobox::Filter and pick":"import { Combobox } from \"pollen-ui\";\nconst timezones = [\n    { value: \"gmt\", label: \"London\", description: \"GMT · UTC+0\" },\n    { value: \"cest\", label: \"Berlin\", description: \"CEST · UTC+2\" },\n    { value: \"jst\", label: \"Tokyo\", description: \"JST · UTC+9\" },\n];\nconst [zone, setZone] = useState(\"cest\");\n<Combobox options={timezones} value={zone} onValueChange={setZone} placeholder=\"Pick a timezone…\"/>;\n","pagination::Many pages":"import { Pagination } from \"pollen-ui\";\n<Pagination total={24} defaultValue={9} aria-label=\"Deployment pages\"/>;\n","pagination::Compact":"<Pagination total={12} defaultValue={4} compact aria-label=\"Compact pagination\"/>;\n","rating::Interactive":"import { useState } from \"react\";\nimport { Rating } from \"pollen-ui\";\nconst [score, setScore] = useState(4);\n<Rating value={score} onValueChange={setScore} aria-label=\"Your rating\"/>;\n","rating::Labels and fractional":"<Rating defaultValue={0} labels={[\"Poor\", \"Fair\", \"Good\", \"Great\", \"Exceptional\"]}/>;\n<Rating value={4.5} readOnly/>;\n{ /* fractional fill */ }\n","rating::Read only":"<Rating value={5} readOnly hideValue/>;\n","rating::Glyphs and tones":"import { Rating } from \"pollen-ui\";\n<Rating glyph=\"heart\" tone=\"rose\" caption=\"1,204 loves\"/>;\n<Rating glyph=\"thumbs\" tone=\"mint\" caption=\"Was this helpful?\"/>;\n<Rating tone=\"accent\" size=\"lg\" caption=\"Rate this release\"/>;\n","rating::Half steps and clearing":"import { Rating } from \"pollen-ui\";\n<Rating allowHalf clearable labels={[\"\", \"\", \"OK\", \"Good\", \"Great\"]} caption=\"Half steps with the pointer. Escape clears.\"/>;\n","tag-input::Team roles":"import { TagInput } from \"pollen-ui\";\nconst [roles, setRoles] = useState([\"design\", \"frontend\", \"docs\"]);\n<TagInput value={roles} onValueChange={setRoles} placeholder=\"Add role…\"/>;\n","tag-input::Limited and validated":"<TagInput max={4} unique placeholder=\"Up to 4 tags…\"/>;\n","steps::Onboarding":"import { Steps } from \"pollen-ui\";\n<Steps value={1} steps={[\n        { title: \"Workspace\", description: \"Name it\" },\n        { title: \"Invite\", description: \"Add your team\" },\n        { title: \"Deploy\", description: \"Ship it\" },\n    ]}/>;\n","steps::Almost done":"<Steps value={2} steps={[\n        { title: \"Repository\" },\n        { title: \"Build\" },\n        { title: \"Domain\" },\n        { title: \"Live\" },\n    ]}/>;\n","timeline::Deploy log":"import { Timeline } from \"pollen-ui\";\n<Timeline items={[\n        { title: \"Build passed\", meta: \"12:04:32\", tone: \"success\" },\n        { title: \"Tests green\", meta: \"12:04:11\", tone: \"success\" },\n        { title: \"Uploading artifacts\", meta: \"12:03:48\", tone: \"accent\" },\n        { title: \"Queued by push to main\", meta: \"12:03:40\" },\n    ]}/>;\n","empty-state::No results":"import { Button, EmptyState, IconSearch } from \"pollen-ui\";\n<EmptyState icon={<IconSearch />} title=\"No deployments found\" description=\"Try a different branch, or clear the status filter.\" action={<Button size=\"sm\" variant=\"secondary\">Clear filters</Button>}/>;\n","empty-state::First run":"import { Button, EmptyState, IconPackage } from \"pollen-ui\";\n<EmptyState icon={<IconPackage />} title=\"No projects yet\" description=\"Import a repository and your first deploy takes about a minute.\" action={<Button size=\"sm\">New project</Button>} secondaryAction={<Button size=\"sm\" variant=\"ghost\">Read the guide</Button>}/>;\n","empty-state::Scenes and tones":"import { EmptyState } from \"pollen-ui\";\n<EmptyState scene=\"search\" tone=\"accent\" title=\"No matches\"/>;\n<EmptyState scene=\"inbox\" title=\"Inbox zero\"/>;\n<EmptyState scene=\"error\" tone=\"danger\" title=\"Build failed\"/>;\n<EmptyState scene=\"chat\" plain title=\"No messages yet\"/>;\n","stat::Metrics":"import { Stat } from \"pollen-ui\";\n<Stat value=\"48,201\" label=\"Requests today\" delta={12.4} deltaLabel=\"vs yesterday\"/>;\n<Stat value=\"99.98%\" label=\"Uptime, 30 days\" delta={0.02} deltaLabel=\"vs last month\"/>;\n<Stat value=\"312\" label=\"Open PRs\" delta={-8.1} deltaLabel=\"vs last week\"/>;\n","number-ticker::In view":"import { NumberTicker } from \"pollen-ui\";\n<NumberTicker value={46}/>;\n<NumberTicker value={23.4} decimals={1} suffix=\" kB\"/>;\n<NumberTicker value={99.98} decimals={2} suffix=\"%\"/>;\n","typewriter::Headline":"import { Typewriter } from \"pollen-ui\";\n<Typewriter text=\"npm install pollen-ui\" startOnView/>;\n","typewriter::Loop":"<Typewriter text=\"Build interfaces that feel finished.\" loop holdTime={1800}/>;\n","chat::Live conversation":"import { ChatThread, ChatInput, useChat } from \"pollen-ui\";\nconst chat = useChat({\n    autoReply: {\n        author: { name: \"Ava Chen\" },\n        messages: [\"Shipped.\", \"Open source is undefeated.\"],\n    },\n});\n<div className=\"flex h-[440px] flex-col\">\n  <ChatThread messages={chat.messages} typing={chat.typing} onReact={chat.react}/>\n  <ChatInput onSend={chat.send} maxLength={280}/>\n</div>;\n","activity-heatmap::Half a year of deploys":"import { ActivityHeatmap } from \"pollen-ui\";\nconst data = [\n    { date: \"2026-06-01\", count: 7 },\n    { date: \"2026-06-02\", count: 12 },\n    // ...one entry per measured day; missing days read as zero.\n];\n<ActivityHeatmap data={data} weeks={30}/>;\n","activity-heatmap::Bigger cells, weekday labels":"import { ActivityHeatmap } from \"pollen-ui\";\nconst data = [\n    { date: \"2026-09-01\", count: 9 },\n    { date: \"2026-09-04\", count: 14 },\n    { date: \"2026-09-09\", count: 3 },\n    { date: \"2026-09-12\", count: 18 },\n    { date: \"2026-09-15\", count: 7 },\n    { date: \"2026-09-18\", count: 12 },\n    { date: \"2026-09-21\", count: 5 },\n    { date: \"2026-09-24\", count: 16 },\n    { date: \"2026-09-27\", count: 8 },\n    { date: \"2026-09-30\", count: 2 },\n    { date: \"2026-10-02\", count: 11 },\n    { date: \"2026-10-04\", count: 19 },\n];\n<ActivityHeatmap data={data} weeks={18} cellSize={14} levels={5} weekdayLabels/>;\n// The legend under this demo is plain markup:\n// color-mix(in srgb, var(--pollen-accent) N%, var(--pollen-fill)).\n","tabs::Enclosed":"import { Tabs, TabsContent, TabsList, TabsTrigger } from \"pollen-ui\";\n<Tabs defaultValue=\"preview\">\n  <TabsList>\n    <TabsTrigger value=\"preview\">Preview</TabsTrigger>\n    <TabsTrigger value=\"code\">Code</TabsTrigger>\n    <TabsTrigger value=\"logs\">Logs</TabsTrigger>\n  </TabsList>\n  <TabsContent value=\"preview\">A live rendering of your page.</TabsContent>\n  <TabsContent value=\"code\">The source that produced this deployment.</TabsContent>\n  <TabsContent value=\"logs\">Build output, streamed as it happens.</TabsContent>\n</Tabs>;\n","tabs::Underline":"<Tabs defaultValue=\"overview\" variant=\"line\">\n  <TabsList>\n    <TabsTrigger value=\"overview\">Overview</TabsTrigger>\n    <TabsTrigger value=\"analytics\">Analytics</TabsTrigger>\n    <TabsTrigger value=\"domains\">Domains</TabsTrigger>\n  </TabsList>\n  <TabsContent value=\"overview\">Traffic, performance and errors at a glance.</TabsContent>\n</Tabs>;\n","breadcrumb::Basic":"import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbPage, BreadcrumbSeparator, } from \"pollen-ui\";\n<Breadcrumb>\n  <BreadcrumbItem><BreadcrumbLink href=\"/\">Docs</BreadcrumbLink></BreadcrumbItem>\n  <BreadcrumbSeparator />\n  <BreadcrumbItem><BreadcrumbLink href=\"/components\">Components</BreadcrumbLink></BreadcrumbItem>\n  <BreadcrumbSeparator />\n  <BreadcrumbItem><BreadcrumbPage>Breadcrumb</BreadcrumbPage></BreadcrumbItem>\n</Breadcrumb>;\n","accordion::Frequently asked":"import { Accordion, AccordionContent, AccordionItem, AccordionTrigger, } from \"pollen-ui\";\n<Accordion type=\"single\">\n  <AccordionItem value=\"what\">\n    <AccordionTrigger value=\"what\">What is Pollen UI?</AccordionTrigger>\n    <AccordionContent value=\"what\">\n      A React component library for Next.js.\n    </AccordionContent>\n  </AccordionItem>\n</Accordion>;\n","accordion::Variants and icons":"import { Accordion, AccordionContent, AccordionItem, AccordionTrigger, IconGauge, } from \"pollen-ui\";\n<Accordion type=\"single\" variant=\"card\" icon=\"chevron\">\n  <AccordionItem value=\"plan\">\n    <AccordionTrigger value=\"plan\" leading={<IconGauge />} meta=\"3 seats\">\n      Team workspaces\n    </AccordionTrigger>\n    <AccordionContent value=\"plan\">...</AccordionContent>\n  </AccordionItem>\n</Accordion>;\n<Accordion type=\"single\" variant=\"bordered\" icon=\"arrow\">...</Accordion>;\n","avatar::Photos":"import { Avatar, AvatarGroup } from \"pollen-ui\";\n// alt defaults to the fallback name, so every photo\n// announces the person it shows.\n<Avatar size={32} src=\"/avatars/ada.jpg\" fallback=\"Ada Lovelace\"/>;\n<AvatarGroup max={4}>\n  <Avatar src=\"/avatars/jo.jpg\" fallback=\"Jo Chen\"/>\n  <Avatar src=\"/avatars/sam.jpg\" fallback=\"Sam Ortiz\"/>\n  <Avatar src=\"/avatars/rae.jpg\" fallback=\"Rae Kim\"/>\n  <Avatar src=\"/avatars/tim.jpg\" fallback=\"Tim Blum\"/>\n  <Avatar src=\"/avatars/nia.jpg\" fallback=\"Nia West\"/>\n</AvatarGroup>;\n","avatar::Presence":"import { Avatar } from \"pollen-ui\";\n// The dot is role=\"img\" with a spoken label:\n// screen readers hear \"Online\", not just a color.\n<Avatar status=\"online\" src=\"/avatars/jo.jpg\" fallback=\"Jo Chen\"/>;\n<Avatar status=\"away\" src=\"/avatars/sam.jpg\" fallback=\"Sam Ortiz\"/>;\n<Avatar status=\"busy\" src=\"/avatars/rae.jpg\" fallback=\"Rae Kim\"/>;\n<Avatar status=\"offline\" src=\"/avatars/tim.jpg\" fallback=\"Tim Blum\"/>;\n","avatar::Variants":"import { Avatar } from \"pollen-ui\";\n<Avatar fallback=\"Ada Lovelace\"/>;\n<Avatar fallback=\"Ada Lovelace\" variant=\"accent\"/>;\n<Avatar fallback=\"Ada Lovelace\" variant=\"inverted\"/>;\n<Avatar fallback=\"Grace Hopper\" shape=\"square\"/>;\n<Avatar fallback=\"Rae Kim\" shape=\"square\" variant=\"accent\" status=\"offline\"/>;\n","avatar::Gradient fallbacks":"import { Avatar } from \"pollen-ui\";\n// The duotone is derived from the name: the same person gets the\n// same colours everywhere, with no request to any server.\n<Avatar fallback=\"Ada Lovelace\" variant=\"gradient\"/>;\n<Avatar fallback=\"Grace Hopper\" variant=\"gradient\" status=\"online\"/>;\n<Avatar fallback=\"Sam Ortiz\" variant=\"gradient\" shape=\"square\"/>;\n","alert::Variants":"import { Alert } from \"pollen-ui\";\n<Alert title=\"Heads up\">Prices change on the first of the month.</Alert>;\n<Alert variant=\"success\" title=\"Deployment complete\">pollen-web is live.</Alert>;\n<Alert variant=\"warning\" title=\"Approaching limit\">You have used 90 percent of your bandwidth.</Alert>;\n<Alert variant=\"danger\" title=\"Build failed\">One test did not pass.</Alert>;\n","alert::Dismissible":"<Alert variant=\"success\" title=\"Backup finished\" dismissible>\n  1,204 files synced. This alert collapses away when dismissed.\n</Alert>;\n","skeleton::Profile card":"import { Skeleton } from \"pollen-ui\";\n<div className=\"flex items-center gap-4 rounded-xl bg-card p-5 shadow-[var(--pollen-shadow-sm)]\">\n  <Skeleton className=\"h-10 w-10 rounded-full\"/>\n  <div className=\"flex-1 space-y-2\">\n    <Skeleton className=\"h-3.5 w-2/3\"/>\n    <Skeleton className=\"h-3 w-1/2\"/>\n  </div>\n</div>;\n","skeleton::Shimmer and text":"import { Skeleton, SkeletonText } from \"pollen-ui\";\n<Skeleton shape=\"circle\" className=\"h-11 w-11\" effect=\"shimmer\"/>;\n<SkeletonText lines={3} effect=\"shimmer\"/>;\n<Skeleton shape=\"text\" className=\"w-24\"/>;\n","spinner::Sizes":"import { Spinner } from \"pollen-ui\";\n<Spinner size={16}/>;\n<span className=\"flex items-center gap-2 text-sm\">\n  <Spinner size={16}/> Loading\n</span>;\n","progress::Basic and indeterminate":"import { Progress } from \"pollen-ui\";\n<Progress value={62} striped/>;\n<Progress aria-label=\"Loading\"/>;\n{ /* indeterminate */ }\n","progress::Colors, sizes and readouts":"<Progress value={86} color=\"success\" showValue/>;\n<Progress value={40} color=\"warning\" size=\"md\" showValue/>;\n<Progress value={22} color=\"danger\" size=\"xs\" showValue/>;\n","kbd::Shortcuts":"import { Kbd } from \"pollen-ui\";\n<span className=\"flex items-center gap-1.5 text-sm\">\n  <Kbd>⌘</Kbd> <Kbd>K</Kbd> to search\n</span>;\n","table::Sorting":"import { DataTable } from \"pollen-ui\";\nconst members = [\n    { name: \"Ada Lovelace\", role: \"Owner\", seats: 24, plan: \"Enterprise\" },\n    { name: \"Grace Hopper\", role: \"Admin\", seats: 12, plan: \"Pro\" },\n    { name: \"Alan Turing\", role: \"Developer\", seats: 3, plan: \"Hobby\" },\n    { name: \"Katherine Johnson\", role: \"Developer\", seats: 8, plan: \"Pro\" },\n];\nconst columns = [\n    { key: \"name\", header: \"Name\", sortable: true, value: (m) => m.name },\n    { key: \"role\", header: \"Role\", value: (m) => m.role },\n    { key: \"seats\", header: \"Seats\", sortable: true, align: \"right\", value: (m) => m.seats },\n    { key: \"plan\", header: \"Plan\", sortable: true, align: \"right\", value: (m) => m.plan },\n];\n<DataTable rows={members} columns={columns} getRowId={(m) => m.name} initialSort={{ key: \"seats\", dir: \"desc\" }}/>;\n","card::Basic":"import { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from \"pollen-ui\";\n<Card className=\"max-w-[340px]\">\n  <CardHeader>\n    <CardTitle>Deploy hooks</CardTitle>\n    <CardDescription>Trigger a build with a single POST request.</CardDescription>\n  </CardHeader>\n  <CardContent>\n    <p className=\"rounded-md bg-fill px-3 py-2 font-mono text-xs\">POST /api/v1/deploy</p>\n  </CardContent>\n  <CardFooter className=\"justify-end gap-2\">\n    <Button variant=\"ghost\">Cancel</Button>\n    <Button>Create hook</Button>\n  </CardFooter>\n</Card>;\n","code-block::Basic":"import { CodeBlock } from \"pollen-ui\";\nconst source = [\n    'import { Button } from \"pollen-ui\";',\n    '',\n    'export default function Page() {',\n    '  return <Button>Ship it</Button>;',\n    '}',\n].join(\"\\\\n\");\n<CodeBlock filename=\"app/page.tsx\" language=\"tsx\" code={source}/>;\n","code-block::Terminal":"import { CodeBlock } from \"pollen-ui\";\nconst commands = [\n    \"# Install the library\",\n    \"npm install pollen-ui\",\n    \"\",\n    \"# Add the stylesheet to your entry\",\n    '# import \"pollen-ui/styles.css\";',\n].join(\"\\\\n\");\n<CodeBlock filename=\"terminal\" language=\"bash\" code={commands}/>;\n","segmented-control::Basic":"import { SegmentedControl } from \"pollen-ui\";\n<SegmentedControl defaultValue=\"week\" options={[\n        { value: \"day\", label: \"Day\" },\n        { value: \"week\", label: \"Week\" },\n        { value: \"month\", label: \"Month\" },\n    ]}/>;\n","segmented-control::Counts, sizes and pill":"<SegmentedControl fullWidth defaultValue=\"all\" options={[\n        { value: \"all\", label: \"All\", badge: 24 },\n        { value: \"unread\", label: \"Unread\", badge: 3 },\n        { value: \"sent\", label: \"Sent\" },\n    ]}/>;\n<SegmentedControl shape=\"pill\" size=\"lg\" defaultValue=\"ship\" options={[{ value: \"ship\", label: \"Ship it\" }, { value: \"hold\", label: \"Hold\" }]}/>;\n","progress-ring::Sizes":"<ProgressRing value={25} size={48} thickness={5}/>;\n<ProgressRing value={62} size={64} thickness={6}/>;\n<ProgressRing value={90} size={84} thickness={7}/>;\n","progress-ring::Semantic colors":"<ProgressRing value={100} variant=\"success\" label=\"Done\"/>;\n<ProgressRing value={54} variant=\"warning\" label=\"54%\"/>;\n<ProgressRing value={96} variant=\"danger\" label=\"96%\"/>;\n","progress-ring::With custom content":"<ProgressRing value={72} showValue={false} aria-label=\"Storage\"/>;\n","reveal::Basic":"import { Reveal } from \"pollen-ui\";\n<Reveal>\n  <div className=\"rounded-xl bg-card p-5 shadow-[var(--pollen-shadow-sm)]\">...</div>\n</Reveal>;\n","text-reveal::Headline":"import { TextReveal } from \"pollen-ui\";\n<TextReveal text=\"Ship interfaces that feel considered.\" className=\"text-2xl font-semibold tracking-tight\"/>;\n","marquee::Component ticker":"import { Marquee } from \"pollen-ui\";\nconst names = [\n    \"Button\", \"Input\", \"Select\", \"Switch\", \"Tabs\", \"Tooltip\", \"Modal\",\n    \"Toast\", \"Command\", \"Accordion\", \"Avatar\", \"Table\", \"Slider\", \"Progress\",\n];\n<Marquee duration={22}>\n  {names.map((name) => (<span key={name} className=\"mx-1.5 rounded-full bg-fill px-4 py-2 text-sm\">\n      {name}\n    </span>))}\n</Marquee>;\n","scroll-progress::Bound to a pane":"import { useRef } from \"react\";\nimport { ScrollProgress } from \"pollen-ui\";\nconst paneRef = useRef(null);\n<div className=\"relative overflow-hidden rounded-2xl bg-card\">\n  <ScrollProgress target={paneRef} className=\"absolute inset-x-0 top-0 h-[2px] origin-left bg-accent\"/>\n  <div ref={paneRef} className=\"h-44 overflow-y-auto\">\n    {/* scrollable content */}\n  </div>\n</div>;\n","scroll-progress::Anchored to the page":"import { ScrollProgress } from \"pollen-ui\";\n// Place it once, near the root:\n<ScrollProgress />;\n","parallax::Drifting panel":"import { Parallax } from \"pollen-ui\";\n<Parallax speed={0.1}>\n  <div className=\"rounded-xl bg-card px-5 py-3 text-sm shadow-[var(--pollen-shadow-sm)]\">\n    Scroll the page and watch this drift\n  </div>\n</Parallax>;\n","parallax::Drift, rotate and scale":"import { Parallax } from \"pollen-ui\";\n<Parallax speed={0.16} rotate={5} scale={0.12}>\n  <div className=\"rounded-2xl bg-card px-6 py-4 shadow-md\">{}/* front layer *\\/}</div>\n</Parallax>\n<Parallax speed={-0.06} axis=\"x\">\n<div>{\\/* back layer, sideways, opposite direction *\\/}</div>\n</Parallax>\n\\/* front layer *\\/}</div>\n</Parallax>;\n<Parallax speed={-0.06} axis=\"x\">\n  <div>{}/* back layer, sideways, opposite direction *\\/}</div>\n</Parallax>\n\\/* back layer, sideways, opposite direction *\\/}</div>\n</Parallax>;\n","magnetic-button::Gravity":"import { MagneticButton } from \"pollen-ui\";\n<MagneticButton size=\"lg\" shine>\n  Get Started\n</MagneticButton>;\n","dock::Magnification":"import { Dock, IconDeploy, IconGauge } from \"pollen-ui\";\n<Dock size={46} items={[\n        { label: \"Deploy\", icon: <IconDeploy /> },\n        { label: \"Metrics\", icon: <IconGauge /> },\n    ]}/>;\n","dock::Pinned left, labels always":"import { Dock } from \"pollen-ui\";\n<Dock position=\"left\" labelMode=\"always\" items={[\n        { label: \"Deploy\", icon: <IconDeploy />, separator: true },\n        { label: \"Metrics\", icon: <IconGauge />, badge: 3 },\n    ]}/>;\n","odometer::Rolling digits":"import { Odometer } from \"pollen-ui\";\n<Odometer value={24680} separator=\",\"/>;\n","odometer::Money, units, compact":"import { Odometer } from \"pollen-ui\";\n<Odometer value={98421.5} prefix=\"$\" separator=\",\" precision={1}/>;\n<Odometer value={43812} compact/>;\n<Odometer value={-12} digits={3}/>;\n","kinetic-headline::Title card":"import { KineticHeadline } from \"pollen-ui\";\n<KineticHeadline as=\"h3\" text=\"Ship the small details\"/>;\n","kinetic-headline::By letter, with highlights":"import { KineticHeadline } from \"pollen-ui\";\n<KineticHeadline by=\"char\" variant=\"drop\" text=\"Design at speed\" highlight={[\"speed\"]}/>;\n","scramble-text::Decode on hover":"import { ScrambleText } from \"pollen-ui\";\n<ScrambleText text=\"access granted\" trigger=\"hover\" className=\"font-mono text-lg\"/>;\n","scramble-text::Presets and loop":"import { ScrambleText } from \"pollen-ui\";\n<ScrambleText text=\"0x5F3759DF\" preset=\"hex\" trigger=\"mount\"/>;\n<ScrambleText text=\"░▒▓ decoding\" preset=\"blocks\" loop={3600}/>;\n","tilt-card::Perspective":"import { TiltCard } from \"pollen-ui\";\n<TiltCard maxTilt={10} glare className=\"rounded-2xl bg-card p-5\">\n  ...\n</TiltCard>;\n","ticket-card::Admit one":"import { TicketCard } from \"pollen-ui\";\n<TicketCard stub={<span>No. 0042</span>}>\n  <h4>Night Bloom Society</h4>\n  <p>Table for two</p>\n</TicketCard>;\n","ticket-card::Vertical, accent edge":"import { TicketCard } from \"pollen-ui\";\n<TicketCard orientation=\"vertical\" accentEdge stub={<span>Gate 4 · 19:30</span>}>\n  <h4>Night Bloom Society</h4>\n</TicketCard>;\n","slide-to-confirm::Deliberate actions":"import { SlideToConfirm, toast } from \"pollen-ui\";\n<SlideToConfirm label=\"Slide to confirm\" onConfirm={async () => {\n        await deleteProject(id);\n        toast.success(\"pollen-web deleted\");\n    }}/>;\n","slide-to-confirm::Destructive red":"import { SlideToConfirm, toast } from \"pollen-ui\";\n<SlideToConfirm tone=\"danger\" label=\"Slide to delete\" successLabel=\"Deleted\" onConfirm={() => toast.success(\"Project deleted\")}/>;\n","pressable-card::Blocks you can push":"import { PressableCard, toast } from \"pollen-ui\";\n<PressableCard depth=\"md\" onClick={() => toast.success(\"Pressed\")}>\n  <h4>Deployments</h4>\n  <p>Press it. It compresses into its own shadow.</p>\n</PressableCard>;\n","compare-slider::Photo retouch":"import { CompareSlider } from \"pollen-ui\";\n<CompareSlider className=\"h-[280px] w-full max-w-[420px] rounded-2xl ring-1 ring-[var(--pollen-border)]\" before={<img src=\"/avatars/grace.jpg\" alt=\"Before: the portrait in grayscale\" className=\"h-full w-full object-cover grayscale brightness-90\" draggable={false}/>} after={<img src=\"/avatars/grace.jpg\" alt=\"After: the portrait in full color\" className=\"h-full w-full object-cover\" draggable={false}/>}/>;\n","compare-slider::Hover mode over UI states":"import { CompareSlider } from \"pollen-ui\";\n// The layers are not limited to images: a flat wireframe\n// against the themed build of the same screen.\nfunction WireframeCard() {\n    return (<div className=\"flex h-40 flex-col justify-between bg-fill p-4\">\n      <div className=\"h-3 w-1/3 rounded-full bg-fill-strong\"/>\n      <div className=\"space-y-1.5\">\n        <div className=\"h-2 w-full rounded-full bg-fill-strong\"/>\n        <div className=\"h-2 w-4/5 rounded-full bg-fill-strong\"/>\n      </div>\n      <div className=\"flex gap-1.5\">\n        <div className=\"h-6 w-16 rounded-md bg-fill-strong\"/>\n        <div className=\"h-6 w-16 rounded-md bg-fill-strong\"/>\n      </div>\n    </div>);\n}\nfunction ThemedCard() {\n    return (<div className=\"flex h-40 flex-col justify-between bg-card p-4\">\n      <p className=\"text-sm font-medium text-foreground\">Relay dashboard</p>\n      <div className=\"space-y-1.5 text-[13px] text-muted-foreground\">\n        <p>Deploys are green across every region.</p>\n        <p>Queue depth is back under the alert line.</p>\n      </div>\n      <div className=\"flex gap-1.5\">\n        <span className=\"rounded-md bg-[var(--pollen-accent)] px-2.5 py-1 text-xs font-medium text-white\">Ship</span>\n        <span className=\"rounded-md bg-fill px-2.5 py-1 text-xs font-medium text-muted-foreground\">Rollback</span>\n      </div>\n    </div>);\n}\n<CompareSlider mode=\"hover\" defaultValue={35} before={<WireframeCard />} after={<ThemedCard />} ariaLabel=\"Divider between the flat wireframe and the themed card\"/>;\n"};

/** Template id -> precomputed JavaScript variant. */
export const templateCodeJs: Record<string, string> = {"navbar-top":"import Link from \"next/link\";\nimport { Avatar, Badge, Button, Kbd, cn } from \"pollen-ui\";\nconst navLinks = [\"Product\", \"Docs\", \"Pricing\", \"Changelog\"];\nexport function NavbarTop() {\n    return (<div className=\"flex h-full min-h-[320px] flex-col bg-background\">\n      <header className=\"flex h-16 items-center gap-6 bg-card/80 px-6 shadow-[var(--pollen-shadow-xs)] backdrop-blur-xl\">\n        <span className=\"flex items-center gap-2.5\">\n          <span className=\"flex h-7 w-7 items-center justify-center rounded-lg bg-foreground text-background\">\n            <Layers className=\"h-4 w-4\"/>\n          </span>\n          <span className=\"text-[15px] font-semibold tracking-[-0.01em]\">Nimbus</span>\n        </span>\n        <nav aria-label=\"Main\" className=\"hidden items-center gap-1 md:flex\">\n          {navLinks.map((link, i) => (<Link key={link} href=\"#\" onClick={(e) => e.preventDefault()} className={cn(\"rounded-full px-3.5 py-2 text-sm transition-colors duration-150\", i === 0\n                ? \"bg-fill font-medium text-foreground\"\n                : \"text-muted-foreground hover:text-foreground\")}>\n              {link}\n            </Link>))}\n        </nav>\n        <div className=\"ml-auto flex items-center gap-2\">\n          <span className=\"hidden h-9 w-52 items-center gap-2 rounded-full bg-fill px-3.5 text-[13px] text-faint sm:flex\">\n            <Search className=\"h-3.5 w-3.5\"/>\n            Search\n            <Kbd className=\"ml-auto bg-card\">⌘K</Kbd>\n          </span>\n          <Button variant=\"ghost\" size=\"icon\" aria-label=\"Notifications\" className=\"relative\">\n            <Bell className=\"h-4 w-4\"/>\n            <Badge count={3} size=\"sm\" className=\"absolute right-1 top-1\"/>\n          </Button>\n          <Avatar size={32} fallback=\"RA\"/>\n        </div>\n      </header>\n\n      {/* Page body hint so the bar reads in context. */}\n      <div className=\"grid flex-1 grid-cols-3 gap-4 p-6 opacity-60\">\n        {[0, 1, 2].map((i) => (<div key={i} className=\"h-20 rounded-2xl bg-fill\"/>))}\n      </div>\n    </div>);\n}\n","navbar-sidebar":"\"use client\";\nimport { useState } from \"react\";\nimport { Avatar, Badge, Kbd, cn } from \"pollen-ui\";\nconst sidebarSections = [\n    {\n        heading: \"Workspace\",\n        items: [\n            { icon: <Home className=\"h-4 w-4\"/>, label: \"Overview\" },\n            { icon: <LayoutGrid className=\"h-4 w-4\"/>, label: \"Projects\", badge: 8 },\n            { icon: <Chat className=\"h-4 w-4\"/>, label: \"Discussions\", badge: 2 },\n        ],\n    },\n    {\n        heading: \"Platform\",\n        items: [\n            { icon: <Deploy className=\"h-4 w-4\"/>, label: \"Deployments\" },\n            { icon: <Gauge className=\"h-4 w-4\"/>, label: \"Analytics\" },\n            { icon: <Box className=\"h-4 w-4\"/>, label: \"Integrations\" },\n        ],\n    },\n];\nexport function NavbarSidebar() {\n    const [active, setActive] = useState(\"Overview\");\n    return (<div className=\"flex h-full min-h-[380px] bg-background\">\n      <aside className=\"flex w-60 shrink-0 flex-col bg-card p-3 shadow-[var(--pollen-shadow-xs)]\">\n        <div className=\"flex items-center justify-between px-2 py-2\">\n          <span className=\"flex items-center gap-2.5\">\n            <span className=\"flex h-7 w-7 items-center justify-center rounded-lg bg-foreground text-background\">\n              <Box className=\"h-4 w-4\"/>\n            </span>\n            <span className=\"text-[14.5px] font-semibold tracking-[-0.01em]\">Atlas</span>\n          </span>\n          <button type=\"button\" aria-label=\"Collapse workspace\" className=\"flex h-7 w-7 items-center justify-center rounded-lg text-faint transition-colors hover:bg-fill hover:text-foreground\">\n            <ChevronDown className=\"h-4 w-4\"/>\n          </button>\n        </div>\n\n        <div className=\"mt-2 flex h-9 items-center gap-2 rounded-xl bg-fill px-3 text-[13px] text-faint\">\n          <Search className=\"h-3.5 w-3.5\"/>\n          Search\n          <Kbd className=\"ml-auto bg-card\">⌘K</Kbd>\n        </div>\n\n        <nav aria-label=\"Workspace\" className=\"mt-4 flex-1 space-y-4\">\n          {sidebarSections.map((section) => (<div key={section.heading}>\n              <p className=\"px-3 pb-1.5 text-[11px] font-semibold uppercase tracking-[0.08em] text-faint\">\n                {section.heading}\n              </p>\n              <div className=\"space-y-0.5\">\n                {section.items.map((item) => {\n                const isActive = active === item.label;\n                return (<button key={item.label} type=\"button\" onClick={() => setActive(item.label)} className={cn(\"flex w-full items-center gap-2.5 rounded-xl px-3 py-2 text-[13.5px] transition-colors duration-150\", isActive\n                        ? \"bg-fill font-medium text-foreground\"\n                        : \"text-muted-foreground hover:bg-fill/60 hover:text-foreground\")}>\n                      <span className={cn(isActive ? \"text-accent\" : \"text-faint\")}>\n                        {item.icon}\n                      </span>\n                      <span className=\"truncate\">{item.label}</span>\n                      {item.badge && <Badge count={item.badge} size=\"sm\" className=\"ml-auto\"/>}\n                    </button>);\n            })}\n              </div>\n            </div>))}\n        </nav>\n\n        <div className=\"flex items-center gap-3 rounded-2xl bg-fill/70 p-3\">\n          <Avatar size={34} fallback=\"JD\"/>\n          <div className=\"min-w-0 flex-1\">\n            <p className=\"truncate text-[13px] font-medium text-foreground\">Jordan Diaz</p>\n            <p className=\"truncate text-[11.5px] text-faint\">jordan@atlas.dev</p>\n          </div>\n          <button type=\"button\" aria-label=\"More\" className=\"flex h-7 w-7 items-center justify-center rounded-lg text-faint transition-colors hover:bg-card hover:text-foreground\">\n            <Dots className=\"h-4 w-4\"/>\n          </button>\n        </div>\n      </aside>\n\n      <div className=\"flex-1 p-6 opacity-60\">\n        <div className=\"grid grid-cols-2 gap-4\">\n          <div className=\"h-24 rounded-2xl bg-fill\"/>\n          <div className=\"h-24 rounded-2xl bg-fill\"/>\n          <div className=\"col-span-2 h-32 rounded-2xl bg-fill\"/>\n        </div>\n      </div>\n    </div>);\n}\n","navbar-command":"import { Button, Kbd } from \"pollen-ui\";\nexport function NavbarCommand() {\n    return (<div className=\"flex h-full min-h-[320px] flex-col bg-background\">\n      <header className=\"flex h-16 items-center gap-4 bg-card px-6 shadow-[var(--pollen-shadow-xs)]\">\n        <span className=\"flex items-center gap-2.5\">\n          <span className=\"flex h-7 w-7 items-center justify-center rounded-lg bg-[var(--pollen-accent)] text-white\">\n            <Deploy className=\"h-4 w-4\"/>\n          </span>\n          <span className=\"text-[15px] font-semibold tracking-[-0.01em]\">Relay</span>\n        </span>\n        <div className=\"mx-auto flex h-10 w-full max-w-md items-center gap-2.5 rounded-xl bg-fill px-3.5 text-[13.5px] text-faint\">\n          <Search className=\"h-4 w-4\"/>\n          <span>Jump to a project, file or action</span>\n          <span className=\"ml-auto flex items-center gap-1 text-[11px]\">\n            <Kbd className=\"bg-card\">⌘</Kbd>\n            <Kbd className=\"bg-card\">K</Kbd>\n          </span>\n        </div>\n        <div className=\"hidden items-center gap-2 md:flex\">\n          <Button size=\"sm\" variant=\"secondary\">\n            <UserPlus className=\"h-3.5 w-3.5\"/>\n            Invite\n          </Button>\n          <Button size=\"sm\">Deploy</Button>\n        </div>\n      </header>\n\n      <div className=\"flex flex-1 items-center justify-center gap-4 p-6 opacity-60\">\n        <div className=\"h-24 w-2/3 rounded-2xl bg-fill\"/>\n        <div className=\"h-24 w-1/3 rounded-2xl bg-fill\"/>\n      </div>\n    </div>);\n}\n","navbar-pill":"\"use client\";\nimport { useState } from \"react\";\nimport { cn } from \"pollen-ui\";\nexport function NavbarPill() {\n    const [active, setActive] = useState(\"Preview\");\n    return (<div className=\"relative flex h-full min-h-[320px] flex-col bg-background\">\n      {/* Soft context so the pill visibly floats. */}\n      <div className=\"grid flex-1 grid-cols-2 gap-4 p-6 opacity-50\">\n        <div className=\"h-28 rounded-2xl bg-fill\"/>\n        <div className=\"h-28 rounded-2xl bg-fill\"/>\n      </div>\n      <nav aria-label=\"Floating\" className=\"absolute inset-x-0 top-5 z-10 mx-auto flex w-fit items-center gap-1 rounded-full bg-card/90 p-1.5 shadow-[var(--pollen-shadow-md)] backdrop-blur-xl\">\n        <span className=\"mr-1 flex h-8 w-8 items-center justify-center rounded-full bg-foreground text-background\">\n          <Palette className=\"h-4 w-4\"/>\n        </span>\n        {[\"Preview\", \"Branches\", \"Insights\", \"Settings\"].map((item) => (<button key={item} type=\"button\" onClick={() => setActive(item)} className={cn(\"relative rounded-full px-4 py-2 text-[13.5px] font-medium outline-none transition-colors duration-150\", active === item\n                ? \"text-foreground\"\n                : \"text-muted-foreground hover:text-foreground\")}>\n            {active === item && (<span className=\"absolute inset-0 rounded-full bg-fill\"/>)}\n            <span className=\"relative z-10\">{item}</span>\n          </button>))}\n        <span className=\"mx-1 h-5 w-px bg-[var(--pollen-separator)]\"/>\n        <button type=\"button\" aria-label=\"Repository\" className=\"flex h-8 w-8 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-fill hover:text-foreground\">\n          <Github className=\"h-4 w-4\"/>\n        </button>\n      </nav>\n    </div>);\n}\n","navbar-dock":"\"use client\";\nimport { useState } from \"react\";\nimport { Badge, cn } from \"pollen-ui\";\nexport function NavbarDock() {\n    const items = [\n        { icon: <Home className=\"h-[45%] w-[45%]\"/>, label: \"Home\" },\n        { icon: <Chat className=\"h-[45%] w-[45%]\"/>, label: \"Chat\", badge: 5 },\n        { icon: <FileCode className=\"h-[45%] w-[45%]\"/>, label: \"Files\" },\n        { icon: <Gauge className=\"h-[45%] w-[45%]\"/>, label: \"Usage\" },\n        { icon: <Box className=\"h-[45%] w-[45%]\"/>, label: \"Apps\" },\n        { icon: <Settings className=\"h-[45%] w-[45%]\"/>, label: \"Settings\" },\n    ];\n    const [active, setActive] = useState(0);\n    return (<div className=\"relative flex h-full min-h-[320px] flex-col justify-end bg-background\">\n      <div className=\"absolute inset-x-6 top-6 grid grid-cols-3 gap-3 opacity-50\">\n        <div className=\"h-16 rounded-2xl bg-fill\"/>\n        <div className=\"h-16 rounded-2xl bg-fill\"/>\n        <div className=\"h-16 rounded-2xl bg-fill\"/>\n      </div>\n      {/* Dock: pinned to the bottom like a desktop. */}\n      <div className=\"relative z-10 mb-6 flex justify-center pb-2\">\n        <div className=\"flex items-end gap-1.5 rounded-2xl bg-card/85 p-2 shadow-[var(--pollen-shadow-lg)] backdrop-blur-xl\">\n          {items.map((item, i) => (<button key={item.label} type=\"button\" aria-label={item.label} onClick={() => setActive(i)} className=\"group relative flex flex-col items-center\">\n              <span className=\"pointer-events-none absolute -top-9 z-20 whitespace-nowrap rounded-lg bg-foreground px-2 py-1 text-[11px] font-medium text-background opacity-0 shadow-[var(--pollen-shadow-sm)] transition-[opacity,translate] duration-150 group-hover:opacity-100\">\n                {item.label}\n                <span className=\"absolute -bottom-1 left-1/2 h-1.5 w-1.5 -translate-x-1/2 rotate-45 rounded-[1px] bg-foreground\"/>\n              </span>\n              <span className={cn(\"relative flex h-11 w-11 items-center justify-center rounded-xl transition-[background-color,transform] duration-150\", \"bg-fill text-muted-foreground group-hover:-translate-y-1.5 group-hover:bg-fill-strong group-hover:text-foreground\", active === i && \"text-foreground\")}>\n                {item.icon}\n                {item.badge && (<Badge count={item.badge} size=\"sm\" className=\"absolute -right-1.5 -top-1.5\"/>)}\n              </span>\n              <span aria-hidden=\"true\" className={cn(\"mt-1 h-1 w-1 rounded-full transition-colors duration-150\", active === i ? \"bg-accent\" : \"bg-transparent\")}/>\n            </button>))}\n        </div>\n      </div>\n    </div>);\n}\n","navbar-bottom":"\"use client\";\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { Badge, cn } from \"pollen-ui\";\nconst bottomTabs = [\n    { icon: <Home className=\"h-5 w-5\"/>, label: \"Home\" },\n    { icon: <Search className=\"h-5 w-5\"/>, label: \"Search\" },\n    { icon: <Layers className=\"h-5 w-5\"/>, label: \"Library\" },\n    { icon: <Chat className=\"h-5 w-5\"/>, label: \"Inbox\", badge: 3 },\n];\nexport function NavbarBottom() {\n    const [active, setActive] = useState(\"Home\");\n    return (<div className=\"relative flex h-full min-h-[340px] flex-col justify-end bg-background\">\n      {/* Dimmed content skeleton above the bar. */}\n      <div className=\"absolute inset-x-6 top-6 space-y-3 opacity-50\">\n        <div className=\"h-20 rounded-2xl bg-fill\"/>\n        <div className=\"grid grid-cols-2 gap-3\">\n          <div className=\"h-16 rounded-2xl bg-fill\"/>\n          <div className=\"h-16 rounded-2xl bg-fill\"/>\n        </div>\n      </div>\n\n      <nav aria-label=\"Primary\" className=\"relative z-10 m-4 flex items-center justify-around rounded-2xl bg-card/90 p-2 shadow-[var(--pollen-shadow-lg)] backdrop-blur-xl\">\n        {bottomTabs.slice(0, 2).map((tab) => (<BottomTab key={tab.label} tab={tab} active={active === tab.label} onClick={() => setActive(tab.label)}/>))}\n        <button type=\"button\" aria-label=\"Create\" className=\"flex h-11 w-11 items-center justify-center rounded-full bg-foreground text-background shadow-[var(--pollen-shadow-md)] transition-transform duration-150 active:scale-95\">\n          <Plus className=\"h-5 w-5\"/>\n        </button>\n        {bottomTabs.slice(2).map((tab) => (<BottomTab key={tab.label} tab={tab} active={active === tab.label} onClick={() => setActive(tab.label)}/>))}\n      </nav>\n    </div>);\n}\nfunction BottomTab({ tab, active, onClick, }) {\n    return (<button type=\"button\" onClick={onClick} aria-current={active ? \"page\" : undefined} className={cn(\"relative flex flex-col items-center gap-0.5 rounded-xl px-3 py-1.5 transition-colors duration-150\", active ? \"text-foreground\" : \"text-muted-foreground hover:text-foreground\")}>\n      <span className=\"relative\">\n        {tab.icon}\n        {tab.badge && (<Badge count={tab.badge} size=\"sm\" className=\"absolute -right-2 -top-1.5\"/>)}\n      </span>\n      <span className=\"text-[10.5px] font-medium leading-none\">{tab.label}</span>\n      {active && (<motion.span layoutId=\"bottom-tab-dot\" className=\"absolute -bottom-0.5 h-1 w-1 rounded-full bg-accent\"/>)}\n    </button>);\n}\n","navbar-rail":"\"use client\";\nimport { useState } from \"react\";\nimport { Avatar, cn } from \"pollen-ui\";\nconst railItems = [\n    { icon: <Home className=\"h-[18px] w-[18px]\"/>, label: \"Home\" },\n    { icon: <Chat className=\"h-[18px] w-[18px]\"/>, label: \"Threads\", badge: 12 },\n    { icon: <FileCode className=\"h-[18px] w-[18px]\"/>, label: \"Snippets\" },\n    { icon: <Gauge className=\"h-[18px] w-[18px]\"/>, label: \"Usage\" },\n    { icon: <Box className=\"h-[18px] w-[18px]\"/>, label: \"Apps\" },\n];\nexport function NavbarRail() {\n    const [active, setActive] = useState(\"Home\");\n    return (<div className=\"flex h-full min-h-[340px] bg-background\">\n      <aside className=\"flex w-14 flex-col items-center gap-1 border-r border-[var(--pollen-separator)] bg-card py-3\">\n        <span className=\"mb-3 flex h-8 w-8 items-center justify-center rounded-lg bg-foreground text-background\">\n          <Box className=\"h-4 w-4\"/>\n        </span>\n        {railItems.map((item) => {\n            const isActive = active === item.label;\n            return (<button key={item.label} type=\"button\" onClick={() => setActive(item.label)} aria-label={item.label} className={cn(\"group/rail relative flex h-9 w-9 items-center justify-center rounded-xl transition-colors duration-150\", isActive\n                    ? \"bg-fill text-foreground\"\n                    : \"text-faint hover:bg-fill/60 hover:text-foreground\")}>\n              {item.icon}\n              {item.badge && (<span className=\"absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-accent\"/>)}\n              <span className=\"pointer-events-none absolute left-11 z-20 whitespace-nowrap rounded-lg bg-foreground px-2 py-1 text-[11px] font-medium text-background opacity-0 shadow-[var(--pollen-shadow-sm)] transition-opacity duration-150 group-hover/rail:opacity-100\">\n                {item.label}\n              </span>\n            </button>);\n        })}\n        <div className=\"mt-auto flex flex-col items-center gap-1\">\n          <button type=\"button\" aria-label=\"Settings\" className=\"flex h-9 w-9 items-center justify-center rounded-xl text-faint transition-colors hover:bg-fill/60 hover:text-foreground\">\n            <Settings className=\"h-[18px] w-[18px]\"/>\n          </button>\n          <Avatar size={26} fallback=\"RA\"/>\n        </div>\n      </aside>\n      <div className=\"flex-1 p-6 opacity-60\">\n        <div className=\"grid grid-cols-3 gap-4\">\n          <div className=\"h-24 rounded-2xl bg-fill\"/>\n          <div className=\"h-24 rounded-2xl bg-fill\"/>\n          <div className=\"h-24 rounded-2xl bg-fill\"/>\n        </div>\n      </div>\n    </div>);\n}\n","navbar-mega":"\"use client\";\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { AnimatePresence, motion } from \"framer-motion\";\nimport { Badge, Button, cn } from \"pollen-ui\";\nconst megaGroups = [\n    {\n        heading: \"Build\",\n        items: [\n            { icon: <FileCode className=\"h-4 w-4\"/>, label: \"Components\", hint: \"60+ primitives\" },\n            { icon: <Layers className=\"h-4 w-4\"/>, label: \"Templates\", hint: \"Whole pages\" },\n            { icon: <TerminalSquare className=\"h-4 w-4\"/>, label: \"CLI\", hint: \"One command\" },\n        ],\n    },\n    {\n        heading: \"Ship\",\n        items: [\n            { icon: <Deploy className=\"h-4 w-4\"/>, label: \"Deployments\", hint: \"Edge-first\" },\n            { icon: <Gauge className=\"h-4 w-4\"/>, label: \"Observability\", hint: \"Traces, logs\" },\n            { icon: <Settings className=\"h-4 w-4\"/>, label: \"Preview flags\", hint: \"Safe rolls\" },\n        ],\n    },\n];\nexport function NavbarMega() {\n    const [open, setOpen] = useState(false);\n    return (<div className=\"flex h-full min-h-[360px] flex-col bg-background\">\n      <header className=\"relative z-20 flex h-16 items-center justify-between bg-card/80 px-8 shadow-[var(--pollen-shadow-xs)] backdrop-blur-xl\">\n        <span className=\"flex items-center gap-2.5\">\n          <span className=\"flex h-7 w-7 items-center justify-center rounded-lg bg-accent text-[var(--pollen-accent-ink,#fff)]\">\n            <Layers className=\"h-4 w-4\"/>\n          </span>\n          <span className=\"text-[15px] font-semibold tracking-[-0.01em]\">Northwind</span>\n        </span>\n\n        <nav aria-label=\"Main\" className=\"hidden items-center gap-1 md:flex\" onMouseLeave={() => setOpen(false)}>\n          <button type=\"button\" aria-expanded={open} onMouseEnter={() => setOpen(true)} onClick={() => setOpen((o) => !o)} className={cn(\"flex items-center gap-1 rounded-full px-3.5 py-2 text-sm transition-colors duration-150\", open ? \"bg-fill font-medium text-foreground\" : \"text-muted-foreground hover:text-foreground\")}>\n            Product\n            <motion.span animate={{ rotate: open ? 180 : 0 }} transition={{ duration: 0.18 }}>\n              <ChevronDown className=\"h-3.5 w-3.5\"/>\n            </motion.span>\n          </button>\n          {[\"Pricing\", \"Docs\", \"Changelog\"].map((link) => (<Link key={link} href=\"#\" onClick={(e) => e.preventDefault()} className=\"rounded-full px-3.5 py-2 text-sm text-muted-foreground transition-colors duration-150 hover:text-foreground\">\n              {link}\n            </Link>))}\n        </nav>\n\n        <div className=\"flex items-center gap-2\">\n          <Button variant=\"ghost\" size=\"sm\">Sign in</Button>\n          <Button size=\"sm\">Start free</Button>\n        </div>\n      </header>\n\n      <AnimatePresence>\n        {open && (<motion.div initial={{ opacity: 0, y: -6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -6 }} transition={{ duration: 0.16, ease: \"easeOut\" }} className=\"relative z-10 mx-auto -mt-1 w-[560px] max-w-[92%]\" onMouseEnter={() => setOpen(true)} onMouseLeave={() => setOpen(false)}>\n            <div className=\"mt-2 grid grid-cols-[1fr_220px] gap-0 overflow-hidden rounded-2xl bg-card shadow-[var(--pollen-shadow-lg)]\">\n              <div className=\"grid grid-cols-2 gap-6 p-5\">\n                {megaGroups.map((group) => (<div key={group.heading}>\n                    <p className=\"px-2 pb-2 text-[11px] font-semibold uppercase tracking-[0.08em] text-faint\">\n                      {group.heading}\n                    </p>\n                    <div className=\"space-y-0.5\">\n                      {group.items.map((item) => (<a key={item.label} href=\"#\" onClick={(e) => e.preventDefault()} className=\"flex items-start gap-2.5 rounded-xl px-2 py-2 transition-colors duration-150 hover:bg-fill\">\n                          <span className=\"mt-0.5 text-faint\">{item.icon}</span>\n                          <span>\n                            <span className=\"block text-[13.5px] font-medium leading-tight text-foreground\">\n                              {item.label}\n                            </span>\n                            <span className=\"block text-[11.5px] leading-tight text-faint\">\n                              {item.hint}\n                            </span>\n                          </span>\n                        </a>))}\n                    </div>\n                  </div>))}\n              </div>\n              <div className=\"relative flex flex-col justify-end bg-fill p-5\">\n                <Badge variant=\"accent\" size=\"sm\" className=\"absolute left-5 top-5\">New</Badge>\n                <p className=\"text-[13.5px] font-semibold leading-snug text-foreground\">\n                  Templates 2.0\n                </p>\n                <p className=\"mt-1 text-[12px] leading-snug text-muted-foreground\">\n                  Twelve whole-page layouts, theme-aware and copy-paste ready.\n                </p>\n                <Button size=\"sm\" variant=\"secondary\" className=\"mt-3 w-fit\">\n                  Browse\n                  <ArrowRight className=\"h-3.5 w-3.5\"/>\n                </Button>\n              </div>\n            </div>\n          </motion.div>)}\n      </AnimatePresence>\n\n      <div className=\"flex-1 p-8 opacity-60\">\n        <div className=\"mx-auto max-w-md space-y-3\">\n          <div className=\"h-8 w-2/3 rounded-xl bg-fill\"/>\n          <div className=\"h-4 w-full rounded-lg bg-fill\"/>\n          <div className=\"h-4 w-5/6 rounded-lg bg-fill\"/>\n        </div>\n      </div>\n    </div>);\n}\n","hero-centered":"import { Avatar, AvatarGroup, Badge, Button } from \"pollen-ui\";\nexport function HeroCentered() {\n    return (<div className=\"flex h-full min-h-[440px] flex-col items-center justify-center bg-background px-8 py-16 text-center\">\n      <Badge variant=\"accent\" icon={<Palette className=\"h-3 w-3\"/>}>\n        Introducing v2.0\n      </Badge>\n      <h1 className=\"mt-6 max-w-2xl text-balance text-5xl font-semibold leading-[1.05] tracking-[-0.035em]\">\n        Ship your product, not your UI kit\n      </h1>\n      <p className=\"mt-5 max-w-lg text-balance text-lg leading-relaxed text-muted-foreground\">\n        One install gives your team every control, surface and motion\n        curve it needs, in light and dark, from day one.\n      </p>\n      <div className=\"mt-8 flex items-center gap-3\">\n        <Button size=\"lg\">\n          Start building\n          <ArrowRight className=\"h-4 w-4\"/>\n        </Button>\n        <Button size=\"lg\" variant=\"secondary\">\n          <Github className=\"h-4 w-4\"/>\n          Star on GitHub\n        </Button>\n      </div>\n      <div className=\"mt-10 flex items-center gap-3\">\n        <AvatarGroup max={4} className=\"[--avatar-ring:var(--pollen-background)]\">\n          <Avatar size={28} src=\"/avatars/grace.jpg\" fallback=\"Mia Torres\"/>\n          <Avatar size={28} src=\"/avatars/leo.jpg\" fallback=\"Leo Park\"/>\n          <Avatar size={28} src=\"/avatars/mia.jpg\" fallback=\"Ada Quinn\"/>\n          <Avatar size={28} src=\"/avatars/leo.jpg\" fallback=\"Ben Sato\"/>\n          <Avatar size={28} src=\"/avatars/alan.jpg\" fallback=\"Zoe Marsh\"/>\n        </AvatarGroup>\n        <p className=\"text-[13.5px] text-muted-foreground\">\n          Loved by <span className=\"font-medium text-foreground\">12,400+</span> product teams\n        </p>\n      </div>\n    </div>);\n}\n","hero-split":"import { Badge, Button, Kbd, Progress } from \"pollen-ui\";\nfunction InvoiceCard() {\n    return (<div className=\"w-[240px] rounded-2xl bg-card p-4 shadow-[var(--pollen-shadow-md)]\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"text-[13px] font-semibold text-foreground\">Invoice #0042</p>\n        <Badge variant=\"success\" dot size=\"sm\">Paid</Badge>\n      </div>\n      <p className=\"mt-2.5 text-2xl font-semibold tabular-nums tracking-[-0.02em] text-foreground\">\n        $2,480.00\n      </p>\n      <div className=\"mt-3.5 space-y-2.5\">\n        <Progress value={72} color=\"accent\"/>\n        <div className=\"flex justify-between text-[11.5px] text-faint\">\n          <span>Milestones 5 of 7</span>\n          <span>72%</span>\n        </div>\n      </div>\n    </div>);\n}\nfunction DeployCard() {\n    return (<div className=\"w-[230px] rounded-2xl bg-card p-4 shadow-[var(--pollen-shadow-lg)]\">\n      <div className=\"flex items-center gap-2.5\">\n        <span className=\"flex h-8 w-8 items-center justify-center rounded-xl bg-[color-mix(in_srgb,var(--pollen-success)_13%,transparent)] text-success\">\n          <Check className=\"h-4 w-4\"/>\n        </span>\n        <div className=\"min-w-0 flex-1\">\n          <p className=\"text-[13px] font-medium leading-tight text-foreground\">Deployed to prod</p>\n          <p className=\"text-[11.5px] leading-tight text-faint\">edge network · 34 regions</p>\n        </div>\n      </div>\n      <div className=\"mt-3 flex items-center gap-1.5 rounded-lg bg-fill px-2.5 py-1.5 font-mono text-[11px] text-muted-foreground\">\n        <span className=\"h-1.5 w-1.5 rounded-full bg-success\"/>\n        build 4m 12s\n        <Kbd className=\"ml-auto bg-card\">⌘D</Kbd>\n      </div>\n    </div>);\n}\nexport function HeroSplit() {\n    return (<div className=\"@container grid h-full min-h-[440px] items-center gap-10 bg-background px-8 py-14 @xl:grid-cols-2 @2xl:px-14\">\n      <div>\n        <Badge dot variant=\"success\">All systems operational</Badge>\n        <h1 className=\"mt-5 text-balance text-4xl font-semibold leading-[1.06] tracking-[-0.03em] sm:text-5xl\">\n          The control room for your release pipeline\n        </h1>\n        <p className=\"mt-5 max-w-md text-lg leading-relaxed text-muted-foreground\">\n          Watch every build, flag and invoice in one calm surface. Built\n          for teams that ship several times a day.\n        </p>\n        <div className=\"mt-8 flex items-center gap-3\">\n          <Button size=\"lg\">Get started free</Button>\n          <Button size=\"lg\" variant=\"ghost\">\n            Book a demo\n            <ArrowRight className=\"h-4 w-4\"/>\n          </Button>\n        </div>\n        <p className=\"mt-6 text-[13px] text-faint\">\n          Free for 14 days · No card required\n        </p>\n      </div>\n\n      {/* The product, floating on soft depth. Real components only. */}\n      <div className=\"relative mx-auto flex min-h-[320px] w-full max-w-[420px] items-center justify-center\">\n        <div className=\"absolute left-0 top-2 -rotate-2 [transform-style:preserve-3d]\">\n          <DeployCard />\n        </div>\n        <div className=\"relative ml-auto mt-16 rotate-1\">\n          <InvoiceCard />\n        </div>\n        <div className=\"absolute -bottom-2 left-8 right-8 h-6 rounded-[50%] bg-black/10 blur-xl dark:bg-black/40\"/>\n      </div>\n    </div>);\n}\n","hero-statement":"import { CodeBlock, Kbd } from \"pollen-ui\";\nexport function HeroStatement() {\n    return (<div className=\"flex h-full min-h-[440px] flex-col items-center justify-center bg-background px-8 py-16 text-center\">\n      <h1 className=\"max-w-3xl text-balance text-6xl font-semibold leading-[0.98] tracking-[-0.045em] sm:text-7xl\">\n        Build at the speed\n        <br />\n        of a <span className=\"text-accent\">thought</span>\n      </h1>\n      <p className=\"mt-6 max-w-md text-balance text-lg leading-relaxed text-muted-foreground\">\n        Copy one command. Paste one line. Your first component is on\n        screen before your coffee cools.\n      </p>\n      <div className=\"mt-9 w-full max-w-[360px]\">\n        <CodeBlock filename=\"terminal\" language=\"bash\" code=\"npm install @nimbus/core\"/>\n      </div>\n      <div className=\"mt-7 flex items-center gap-2 text-[13px] text-muted-foreground\">\n        <TerminalSquare className=\"h-4 w-4 text-faint\"/>\n        Works with <Kbd className=\"mx-0.5\">npm</Kbd>\n        <Kbd className=\"mx-0.5\">pnpm</Kbd>\n        <Kbd className=\"mx-0.5\">bun</Kbd>\n      </div>\n    </div>);\n}\n","hero-waitlist":"import { Badge, Button, Input } from \"pollen-ui\";\nexport function HeroWaitlist() {\n    return (<div className=\"flex h-full min-h-[440px] flex-col items-center justify-center bg-background px-8 py-16 text-center\">\n      <Badge variant=\"accent\" dot>\n        Cohort 3 opens in March\n      </Badge>\n      <h1 className=\"mt-6 max-w-xl text-balance text-5xl font-semibold leading-[1.05] tracking-[-0.035em]\">\n        The roadmap tool your whole team will actually open\n      </h1>\n      <p className=\"mt-5 max-w-md text-balance text-lg leading-relaxed text-muted-foreground\">\n        One line per week from every team, one calm board for the\n        whole company. Join the waitlist and get the first month free.\n      </p>\n      <form className=\"mt-8 flex w-full max-w-md items-center gap-2\" onSubmit={(e) => e.preventDefault()}>\n        <Input type=\"email\" required placeholder=\"you@company.com\" aria-label=\"Work email\" className=\"flex-1\"/>\n        <Button type=\"submit\" size=\"lg\" className=\"shrink-0\">\n          Join waitlist\n        </Button>\n      </form>\n      <p className=\"mt-3.5 text-[13px] text-faint\">\n        8,214 in line · No spam, one email when your seat opens\n      </p>\n    </div>);\n}\n","hero-metrics":"import { Badge, Button, Odometer } from \"pollen-ui\";\nfunction Metric({ label, value, suffix, precision, }) {\n    return (<div className=\"flex flex-col items-center gap-1.5\">\n      <span className=\"flex items-baseline text-3xl font-semibold tabular-nums tracking-[-0.02em]\">\n        <Odometer value={value} digits={Math.max(2, String(Math.floor(value)).length)} precision={precision} className=\"text-foreground\"/>\n        {suffix && <span className=\"ml-1 text-xl text-muted-foreground\">{suffix}</span>}\n      </span>\n      <span className=\"text-[12.5px] text-muted-foreground\">{label}</span>\n    </div>);\n}\nexport function HeroMetrics() {\n    return (<div className=\"flex h-full min-h-[440px] flex-col items-center justify-center bg-background px-8 py-16 text-center\">\n      <Badge dot variant=\"success\">All regions operational</Badge>\n      <h1 className=\"mt-6 max-w-2xl text-balance text-5xl font-semibold leading-[1.05] tracking-[-0.035em]\">\n        Storage that sits closer to your users\n      </h1>\n      <p className=\"mt-5 max-w-lg text-balance text-lg leading-relaxed text-muted-foreground\">\n        Object storage with a global cache, transparent egress pricing and\n        an API your scripts already speak.\n      </p>\n      <div className=\"mt-9 grid w-full max-w-xl grid-cols-3 gap-6 rounded-2xl bg-card px-6 py-5 shadow-[var(--pollen-shadow-sm)]\">\n        <Metric label=\"Objects served / s\" value={940} suffix=\"k\"/>\n        <Metric label=\"P99 latency\" value={38} suffix=\"ms\"/>\n        <Metric label=\"Uptime, 12 mo\" value={99.99} precision={2} suffix=\"%\"/>\n      </div>\n      <div className=\"mt-8 flex items-center gap-3\">\n        <Button size=\"lg\">Start storing</Button>\n        <Button size=\"lg\" variant=\"secondary\">\n          Read the docs\n        </Button>\n      </div>\n    </div>);\n}\n","hero-appshot":"import { Badge, Button, cn } from \"pollen-ui\";\nfunction AppWindow() {\n    const rows = [\n        { name: \"atlas-web\", env: \"prod\", status: \"Ready\", tone: \"success\" },\n        { name: \"atlas-api\", env: \"prod\", status: \"Building\", tone: \"accent\" },\n        { name: \"docs\", env: \"preview\", status: \"Ready\", tone: \"success\" },\n    ];\n    return (<div className=\"w-[340px] overflow-hidden rounded-2xl bg-card shadow-[var(--pollen-shadow-lg)]\">\n      <div className=\"flex items-center gap-2 border-b border-[var(--pollen-separator)] px-4 py-2.5\">\n        <span className=\"flex gap-1.5\">\n          <span className=\"h-2 w-2 rounded-full bg-fill-strong\"/>\n          <span className=\"h-2 w-2 rounded-full bg-fill-strong\"/>\n          <span className=\"h-2 w-2 rounded-full bg-fill-strong\"/>\n        </span>\n        <span className=\"mx-auto text-[11px] text-faint\">atlas.dev/deploys</span>\n      </div>\n      <div className=\"p-3.5\">\n        <div className=\"flex items-center justify-between pb-3\">\n          <p className=\"text-[13px] font-semibold text-foreground\">Deployments</p>\n          <Button size=\"sm\" variant=\"secondary\">New</Button>\n        </div>\n        <div className=\"space-y-1.5\">\n          {rows.map((row) => (<div key={row.name} className=\"flex items-center gap-2.5 rounded-xl bg-fill/60 px-3 py-2\">\n              <span className={cn(\"h-1.5 w-1.5 shrink-0 rounded-full\", row.tone === \"success\" ? \"bg-success\" : \"bg-accent\")}/>\n              <span className=\"font-mono text-[12px] text-foreground\">{row.name}</span>\n              <span className=\"text-[11px] text-faint\">{row.env}</span>\n              <span className=\"ml-auto text-[11.5px] font-medium text-muted-foreground\">\n                {row.status}\n              </span>\n            </div>))}\n        </div>\n      </div>\n    </div>);\n}\nexport function HeroAppShot() {\n    return (<div className=\"@container grid h-full min-h-[440px] items-center gap-10 bg-background px-8 py-14 @xl:grid-cols-2 @2xl:px-14\">\n      <div>\n        <Badge variant=\"neutral\">v3 · now with rollbacks</Badge>\n        <h1 className=\"mt-5 text-balance text-4xl font-semibold leading-[1.06] tracking-[-0.03em] sm:text-5xl\">\n          Deploys your whole team can read\n        </h1>\n        <p className=\"mt-5 max-w-md text-lg leading-relaxed text-muted-foreground\">\n          Every build, preview and rollback in one calm list. No\n          dashboard archery, no wall of logs unless you ask for them.\n        </p>\n        <div className=\"mt-8 flex items-center gap-3\">\n          <Button size=\"lg\">\n            Deploy your first app\n            <ArrowRight className=\"h-4 w-4\"/>\n          </Button>\n          <Button size=\"lg\" variant=\"ghost\">\n            View changelog\n          </Button>\n        </div>\n      </div>\n      <div className=\"relative flex justify-center lg:justify-end\">\n        <div className=\"relative\">\n          <AppWindow />\n          <div className=\"absolute -bottom-4 left-6 right-6 h-6 rounded-[50%] bg-black/10 blur-xl dark:bg-black/40\"/>\n        </div>\n      </div>\n    </div>);\n}\n","section-pricing":"import { Badge, Button, SegmentedControl, cn } from \"pollen-ui\";\nconst tiers = [\n    {\n        name: \"Hobby\",\n        price: \"$0\",\n        cadence: \"forever\",\n        blurb: \"For the weekend project that deserves real polish.\",\n        features: [\"Up to 3 projects\", \"Community support\", \"Core component set\", \"Light and dark themes\"],\n        cta: \"Start free\",\n        highlighted: false,\n    },\n    {\n        name: \"Pro\",\n        price: \"$24\",\n        cadence: \"per editor / month\",\n        blurb: \"For product teams shipping to customers every week.\",\n        features: [\n            \"Unlimited projects\",\n            \"Priority support, 4h first response\",\n            \"Every component and template\",\n            \"Figma kit with tokens\",\n        ],\n        cta: \"Start 14-day trial\",\n        highlighted: true,\n    },\n    {\n        name: \"Enterprise\",\n        price: \"Custom\",\n        cadence: \"annual\",\n        blurb: \"For platform teams with compliance and scale needs.\",\n        features: [\"SSO and SCIM\", \"Dedicated success engineer\", \"Security review and DPA\", \"On-premise builds\"],\n        cta: \"Talk to sales\",\n        highlighted: false,\n    },\n];\nexport function PricingSection() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"text-center\">\n        <p className=\"text-sm font-semibold text-accent\">Pricing</p>\n        <h2 className=\"mt-3 text-balance text-4xl font-semibold tracking-[-0.03em]\">\n          Start free, scale when it ships\n        </h2>\n        <div className=\"mt-7 flex justify-center\">\n          <SegmentedControl defaultValue=\"monthly\" aria-label=\"Billing period\" options={[\n            { value: \"monthly\", label: \"Monthly\" },\n            { value: \"yearly\", label: \"Yearly\", badge: \"2mo\" },\n        ]}/>\n        </div>\n      </div>\n      <div className=\"mx-auto mt-10 grid max-w-4xl gap-4 @2xl:grid-cols-3\">\n        {tiers.map((tier) => (<div key={tier.name} className={cn(\"relative flex flex-col rounded-3xl bg-card p-7\", tier.highlighted\n                ? \"shadow-[var(--pollen-shadow-lg)] ring-1 ring-[color-mix(in_srgb,var(--pollen-accent)_35%,transparent)]\"\n                : \"shadow-[var(--pollen-shadow-sm)]\")}>\n            {tier.highlighted && (<Badge variant=\"accent\" className=\"absolute -top-2.5 left-6 shadow-[var(--pollen-shadow-xs)]\">\n                Most popular\n              </Badge>)}\n            <p className=\"text-[15px] font-semibold text-foreground\">{tier.name}</p>\n            <p className=\"mt-1 min-h-10 text-[13.5px] leading-snug text-muted-foreground\">{tier.blurb}</p>\n            <p className=\"mt-4 flex items-baseline gap-1.5\">\n              <span className=\"text-4xl font-semibold tracking-[-0.03em] text-foreground\">{tier.price}</span>\n              <span className=\"text-[13px] text-faint\">{tier.cadence}</span>\n            </p>\n            <ul className=\"mt-6 flex-1 space-y-2.5\">\n              {tier.features.map((feature) => (<li key={feature} className=\"flex items-start gap-2.5 text-[13.5px] leading-snug text-muted-foreground\">\n                  <Check className=\"mt-0.5 h-4 w-4 shrink-0 text-accent\"/>\n                  {feature}\n                </li>))}\n            </ul>\n            <Button className=\"mt-7\" variant={tier.highlighted ? \"accent\" : \"secondary\"} fullWidth>\n              {tier.cta}\n            </Button>\n          </div>))}\n      </div>\n    </div>);\n}\n","section-logos":"import { Marquee } from \"pollen-ui\";\nconst customerMarks = [\n    \"Halcyon\", \"Northwind\", \"Atlas\", \"Relay\", \"Vercelia\", \"Quill\",\n    \"Meridian\", \"Foundry\", \"Cobalt\", \"Lumen\",\n];\nexport function LogoMarquee() {\n    return (<div className=\"bg-background px-8 py-12\">\n      <p className=\"text-center text-[13px] font-medium text-faint\">\n        Trusted by product teams at\n      </p>\n      <div className=\"mx-auto mt-6 max-w-4xl\">\n        <Marquee pauseOnHover className=\"opacity-70\">\n          {customerMarks.map((mark) => (<span key={mark} className=\"mx-7 select-none whitespace-nowrap text-lg font-semibold tracking-[-0.01em] text-muted-foreground\">\n              {mark}\n            </span>))}\n        </Marquee>\n      </div>\n    </div>);\n}\n","section-testimonials":"import { Avatar, Rating } from \"pollen-ui\";\nconst quotes = [\n    {\n        quote: \"We replaced six months of interface work with an afternoon. The springs alone are worth the install.\",\n        name: \"Mia Torres\",\n        role: \"Head of Design, Halcyon\",\n        avatar: \"/avatars/grace.jpg\",\n        featured: true,\n    },\n    {\n        quote: \"Finally a library where dark mode is not an afterthought.\",\n        name: \"Leo Park\",\n        role: \"Staff Engineer, Relay\",\n        avatar: \"/avatars/leo.jpg\",\n        featured: false,\n        rating: 5,\n    },\n    {\n        quote: \"Our designers stopped filing pixel tickets. That is the review.\",\n        name: \"Ada Quinn\",\n        role: \"Product Lead, Foundry\",\n        avatar: \"/avatars/mia.jpg\",\n        featured: false,\n        rating: 4.5,\n    },\n];\nexport function Testimonials() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"mx-auto max-w-4xl\">\n        <h2 className=\"text-balance text-center text-4xl font-semibold tracking-[-0.03em]\">\n          Teams ship faster with Pollen\n        </h2>\n        <div className=\"mt-10 grid gap-4 @xl:grid-cols-2\">\n          {quotes.map((q) => q.featured ? (<figure key={q.name} className=\"flex flex-col justify-between rounded-3xl bg-card p-8 shadow-[var(--pollen-shadow-sm)] @xl:row-span-2\">\n                <blockquote className=\"text-balance text-2xl font-medium leading-snug tracking-[-0.015em] text-foreground\">\n                  “{q.quote}”\n                </blockquote>\n                <figcaption className=\"mt-8 flex items-center gap-3\">\n                  <Avatar size={40} src={q.avatar} fallback={q.name}/>\n                  <div>\n                    <p className=\"text-[14.5px] font-medium text-foreground\">{q.name}</p>\n                    <p className=\"text-[12.5px] text-muted-foreground\">{q.role}</p>\n                  </div>\n                </figcaption>\n              </figure>) : (<figure key={q.name} className=\"rounded-3xl bg-card p-6 shadow-[var(--pollen-shadow-sm)]\">\n                <Rating value={q.rating ?? 5} readOnly size=\"sm\"/>\n                <blockquote className=\"mt-3.5 text-[15px] leading-relaxed text-foreground\">\n                  “{q.quote}”\n                </blockquote>\n                <figcaption className=\"mt-5 flex items-center gap-2.5\">\n                  <Avatar size={30} src={q.avatar} fallback={q.name}/>\n                  <div>\n                    <p className=\"text-[13px] font-medium text-foreground\">{q.name}</p>\n                    <p className=\"text-[11.5px] text-muted-foreground\">{q.role}</p>\n                  </div>\n                </figcaption>\n              </figure>))}\n        </div>\n      </div>\n    </div>);\n}\n","section-auth":"import Link from \"next/link\";\nimport { Button, Checkbox, Input, Label } from \"pollen-ui\";\nexport function AuthCard() {\n    return (<div className=\"flex h-full min-h-[440px] items-center justify-center bg-background px-8 py-14\">\n      <div className=\"w-full max-w-[400px] rounded-3xl bg-card p-8 shadow-[var(--pollen-shadow-md)]\">\n        <div className=\"flex flex-col items-center text-center\">\n          <span className=\"flex h-11 w-11 items-center justify-center rounded-2xl bg-foreground text-background\">\n            <Layers className=\"h-5 w-5\"/>\n          </span>\n          <h2 className=\"mt-5 text-2xl font-semibold tracking-[-0.02em]\">Welcome back</h2>\n          <p className=\"mt-1.5 text-[14.5px] text-muted-foreground\">\n            Sign in to your workspace\n          </p>\n        </div>\n\n        <div className=\"mt-7 grid grid-cols-2 gap-2.5\">\n          <Button variant=\"secondary\" fullWidth>\n            <Github className=\"h-4 w-4\"/>\n            GitHub\n          </Button>\n          <Button variant=\"secondary\" fullWidth>\n            <Mail className=\"h-4 w-4\"/>\n            Google\n          </Button>\n        </div>\n\n        <div className=\"my-6 flex items-center gap-3\">\n          <span className=\"h-px flex-1 bg-[var(--pollen-separator)]\"/>\n          <span className=\"text-xs text-faint\">or with email</span>\n          <span className=\"h-px flex-1 bg-[var(--pollen-separator)]\"/>\n        </div>\n\n        <form className=\"space-y-4\" onSubmit={(e) => e.preventDefault()}>\n          <div className=\"space-y-1.5\">\n            <Label htmlFor=\"tpl-email\">Email</Label>\n            <Input id=\"tpl-email\" type=\"email\" placeholder=\"you@company.com\"/>\n          </div>\n          <div className=\"space-y-1.5\">\n            <div className=\"flex items-center justify-between\">\n              <Label htmlFor=\"tpl-password\">Password</Label>\n              <Link href=\"#\" onClick={(e) => e.preventDefault()} className=\"text-xs text-accent hover:underline\">\n                Forgot?\n              </Link>\n            </div>\n            <Input id=\"tpl-password\" type=\"password\" placeholder=\"••••••••\"/>\n          </div>\n          <Checkbox size=\"sm\" defaultChecked>Keep me signed in</Checkbox>\n          <Button type=\"submit\" fullWidth size=\"lg\">\n            <Lock className=\"h-4 w-4\"/>\n            Sign in\n          </Button>\n        </form>\n\n        <p className=\"mt-6 text-center text-[13px] text-muted-foreground\">\n          New here?{\" \"}\n          <Link href=\"#\" onClick={(e) => e.preventDefault()} className=\"font-medium text-accent hover:underline\">\n            Create an account\n          </Link>\n        </p>\n      </div>\n    </div>);\n}\n","section-stats":"import { Odometer } from \"pollen-ui\";\nconst stats = [\n    { icon: <Odometer className=\"h-5 w-5\"/>, value: \"54\", suffix: \"k\", label: \"GitHub stars\" },\n    { icon: <AppWindow className=\"h-5 w-5\"/>, value: \"1.2\", suffix: \"M\", label: \"Weekly installs\" },\n    { icon: <Layers className=\"h-5 w-5\"/>, value: \"54\", suffix: \"\", label: \"Components\" },\n    { icon: <Bolt className=\"h-5 w-5\"/>, value: \"99.98\", suffix: \"%\", label: \"Docs uptime\" },\n];\nexport function StatsBand() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"mx-auto grid max-w-4xl grid-cols-2 gap-4 @2xl:grid-cols-4\">\n        {stats.map((stat) => (<div key={stat.label} className=\"rounded-3xl bg-card p-6 text-center shadow-[var(--pollen-shadow-sm)]\">\n            <span className=\"mx-auto flex h-10 w-10 items-center justify-center rounded-2xl bg-fill text-foreground\">\n              {stat.icon}\n            </span>\n            <p className=\"mt-4 text-3xl font-semibold tabular-nums tracking-[-0.03em] text-foreground\">\n              {stat.value}\n              <span className=\"text-accent\">{stat.suffix}</span>\n            </p>\n            <p className=\"mt-1 text-[13px] text-muted-foreground\">{stat.label}</p>\n          </div>))}\n      </div>\n    </div>);\n}\n","section-bento":"import { Progress } from \"pollen-ui\";\nexport function FeatureGrid() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"mx-auto grid max-w-4xl gap-4 @xl:grid-cols-3\">\n        <div className=\"rounded-3xl bg-card p-7 shadow-[var(--pollen-shadow-sm)] @xl:col-span-2\">\n          <span className=\"flex h-11 w-11 items-center justify-center rounded-2xl bg-fill text-foreground\">\n            <Chart className=\"h-5 w-5\"/>\n          </span>\n          <h3 className=\"mt-5 text-xl font-semibold tracking-[-0.01em]\">Real-time dashboards</h3>\n          <p className=\"mt-2 max-w-md text-[15px] leading-relaxed text-muted-foreground\">\n            Stream live data into components tuned for constant change:\n            numbers that roll, bars that ease, sparklines that breathe.\n          </p>\n          <div className=\"mt-6 space-y-3 rounded-2xl bg-fill/60 p-4\">\n            <div className=\"flex items-center justify-between text-[13px]\">\n              <span className=\"font-medium text-foreground\">API latency</span>\n              <span className=\"tabular-nums text-muted-foreground\">84ms</span>\n            </div>\n            <Progress value={30} color=\"success\" showValue/>\n            <div className=\"flex items-center justify-between text-[13px]\">\n              <span className=\"font-medium text-foreground\">Error rate</span>\n              <span className=\"tabular-nums text-muted-foreground\">0.4%</span>\n            </div>\n            <Progress value={4} color=\"danger\" showValue/>\n          </div>\n        </div>\n        <div className=\"flex flex-col gap-4\">\n          <div className=\"flex-1 rounded-3xl bg-card p-7 shadow-[var(--pollen-shadow-sm)]\">\n            <span className=\"flex h-11 w-11 items-center justify-center rounded-2xl bg-fill text-foreground\">\n              <Palette className=\"h-5 w-5\"/>\n            </span>\n            <h3 className=\"mt-5 text-lg font-semibold tracking-[-0.01em]\">Token theming</h3>\n            <p className=\"mt-2 text-[14.5px] leading-relaxed text-muted-foreground\">\n              Rebrand in one file. Every color, radius and shadow is a\n              CSS variable.\n            </p>\n          </div>\n          <div className=\"flex-1 rounded-3xl bg-card p-7 shadow-[var(--pollen-shadow-sm)]\">\n            <span className=\"flex h-11 w-11 items-center justify-center rounded-2xl bg-fill text-foreground\">\n              <User className=\"h-5 w-5\"/>\n            </span>\n            <h3 className=\"mt-5 text-lg font-semibold tracking-[-0.01em]\">Built-in presence</h3>\n            <p className=\"mt-2 text-[14.5px] leading-relaxed text-muted-foreground\">\n              Avatars, status dots and typing indicators ready for\n              collaborative surfaces.\n            </p>\n          </div>\n        </div>\n      </div>\n    </div>);\n}\n","section-faq":"import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from \"pollen-ui\";\nconst faqs = [\n    {\n        q: \"Can I use Pollen in a commercial product?\",\n        a: \"Yes. Pollen is MIT licensed, so it ships inside client work, internal tools and paid products with no attribution required.\",\n    },\n    {\n        q: \"Does it work with my existing Tailwind setup?\",\n        a: \"Pollen targets Tailwind v4 and ships its tokens as CSS variables. Import the stylesheet once, then use the components alongside your own classes.\",\n    },\n    {\n        q: \"How do themes work?\",\n        a: \"Light and dark are two token sets under .light and .dark. Every component reads the same variables, so a rebrand is one file and a dark mode is one class.\",\n    },\n    {\n        q: \"What about accessibility?\",\n        a: \"Every interactive component is keyboard operable, labelled, and respects prefers-reduced-motion by falling back to instant states.\",\n    },\n];\nexport function FAQSection() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"mx-auto grid max-w-4xl gap-10 @xl:grid-cols-[280px_1fr]\">\n        <div className=\"min-w-0\">\n          <p className=\"text-sm font-semibold text-accent\">FAQ</p>\n          <h2 className=\"mt-3 text-3xl font-semibold tracking-[-0.025em]\">\n            Answers, before the email\n          </h2>\n          <p className=\"mt-3 text-[14.5px] leading-relaxed text-muted-foreground\">\n            The four questions every evaluation asks. Still curious?\n            The docs search knows the rest.\n          </p>\n        </div>\n        <Accordion type=\"single\" defaultValue={[\"faq-1\"]} variant=\"flush\" icon=\"plus\" className=\"min-w-0\">\n          {faqs.map((item, i) => (<AccordionItem key={item.q} value={`faq-${i + 1}`}>\n              <AccordionTrigger value={`faq-${i + 1}`}>{item.q}</AccordionTrigger>\n              <AccordionContent value={`faq-${i + 1}`}>{item.a}</AccordionContent>\n            </AccordionItem>))}\n        </Accordion>\n      </div>\n    </div>);\n}\n","section-newsletter":"import { Badge, Button, Input } from \"pollen-ui\";\nexport function NewsletterBand() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"mx-auto flex max-w-4xl flex-col items-start gap-8 rounded-3xl bg-card p-8 shadow-[var(--pollen-shadow-sm)] sm:p-10 @2xl:flex-row @2xl:items-center\">\n        <div className=\"min-w-0 flex-1\">\n          <Badge variant=\"accent\" size=\"sm\">Monthly</Badge>\n          <h3 className=\"mt-3 text-2xl font-semibold tracking-[-0.02em]\">\n            The Pollen letter\n          </h3>\n          <p className=\"mt-2 max-w-sm text-[14.5px] leading-relaxed text-muted-foreground\">\n            One email a month: new components, motion recipes, and the\n            occasional deep dive. Unsubscribe any time.\n          </p>\n        </div>\n        <form className=\"w-full max-w-sm shrink-0 space-y-2.5\" onSubmit={(e) => e.preventDefault()}>\n          <Input type=\"email\" required placeholder=\"you@company.com\" aria-label=\"Email address\" icon={<Mail className=\"h-4 w-4\"/>}/>\n          <Button type=\"submit\" fullWidth>\n            Subscribe\n            <ArrowRight className=\"h-4 w-4\"/>\n          </Button>\n          <p className=\"text-center text-[12px] text-faint\">\n            12,906 subscribers · No sponsors, no filler\n          </p>\n        </form>\n      </div>\n    </div>);\n}\n","section-changelog":"import { Badge } from \"pollen-ui\";\nconst releases = [\n    {\n        version: \"4.0\",\n        date: \"Nov 2025\",\n        tag: \"Major\",\n        title: \"Premium set: chat, toasts, slide to confirm\",\n        items: [\"Full chat surface with reactions\", \"Stacking toast pile\", \"Pressable cards and dock\"],\n    },\n    {\n        version: \"3.2\",\n        date: \"Sep 2025\",\n        tag: \"Minor\",\n        title: \"Templates and the theme studio\",\n        items: [\"Twelve page templates\", \"Live theme studio\", \"Radius and accent tokens\"],\n    },\n    {\n        version: \"3.1\",\n        date: \"Jul 2025\",\n        tag: \"Patch\",\n        title: \"Motion polish and fixes\",\n        items: [\"Spring presets unified\", \"Reduced-motion fallbacks everywhere\"],\n    },\n];\nexport function ChangelogTimeline() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"mx-auto max-w-3xl\">\n        <h2 className=\"text-balance text-center text-4xl font-semibold tracking-[-0.03em]\">\n          Changelog\n        </h2>\n        <p className=\"mx-auto mt-3 max-w-md text-balance text-center text-[15px] text-muted-foreground\">\n          Every release, dated and plain. No surprise majors.\n        </p>\n        <div className=\"relative mt-10 space-y-8 before:absolute before:bottom-2 before:left-[7px] before:top-2 before:w-px before:bg-[var(--pollen-separator)]\">\n          {releases.map((release) => (<div key={release.version} className=\"relative pl-8\">\n              <span className=\"absolute left-0 top-1.5 h-[15px] w-[15px] rounded-full border-[3px] border-background bg-accent shadow-[0_0_0_1px_var(--pollen-separator)]\"/>\n              <div className=\"flex flex-wrap items-center gap-2.5\">\n                <span className=\"text-[15px] font-semibold text-foreground\">\n                  v{release.version}\n                </span>\n                <Badge variant={release.tag === \"Major\"\n                ? \"accent\"\n                : release.tag === \"Minor\"\n                    ? \"success\"\n                    : \"neutral\"} size=\"sm\">\n                  {release.tag}\n                </Badge>\n                <span className=\"text-[12.5px] text-faint\">{release.date}</span>\n              </div>\n              <p className=\"mt-1.5 text-[14.5px] font-medium text-foreground\">\n                {release.title}\n              </p>\n              <ul className=\"mt-2 space-y-1\">\n                {release.items.map((item) => (<li key={item} className=\"flex items-start gap-2 text-[13.5px] leading-snug text-muted-foreground\">\n                    <Check className=\"mt-0.5 h-3.5 w-3.5 shrink-0 text-faint\"/>\n                    {item}\n                  </li>))}\n              </ul>\n            </div>))}\n        </div>\n      </div>\n    </div>);\n}\n","section-cta":"import { Button } from \"pollen-ui\";\nexport function CtaBanner() {\n    return (<div className=\"bg-background px-8 py-14\">\n      <div className=\"relative mx-auto max-w-4xl overflow-hidden rounded-[32px] bg-foreground px-8 py-16 text-center text-background shadow-[var(--pollen-shadow-lg)]\">\n        <div aria-hidden=\"true\" className=\"absolute left-1/2 top-[-140px] h-[320px] w-[560px] -translate-x-1/2 rounded-[100%] bg-[radial-gradient(closest-side,rgba(255,255,255,0.14),transparent)]\"/>\n        <h2 className=\"relative text-balance text-4xl font-semibold tracking-[-0.03em]\">\n          Your next release starts here\n        </h2>\n        <p className=\"relative mx-auto mt-4 max-w-md text-balance text-[17px] leading-relaxed text-background/70\">\n          One install away from the polish your product deserves.\n        </p>\n        <div className=\"relative mt-9 flex flex-col items-center justify-center gap-3 sm:flex-row\">\n          <Button size=\"lg\" className=\"bg-background text-foreground hover:bg-background/90\">\n            Get started\n            <ArrowRight className=\"h-4 w-4\"/>\n          </Button>\n          <Button size=\"lg\" variant=\"ghost\" className=\"text-background hover:bg-white/10\">\n            <Github className=\"h-4 w-4\"/>\n            View source\n          </Button>\n        </div>\n      </div>\n    </div>);\n}\n","section-footer":"import Link from \"next/link\";\nimport { Kbd } from \"pollen-ui\";\nconst footerColumns = [\n    { heading: \"Product\", links: [\"Components\", \"Templates\", \"Playground\", \"Changelog\"] },\n    { heading: \"Resources\", links: [\"Documentation\", \"Guides\", \"Figma kit\", \"Roadmap\"] },\n    { heading: \"Company\", links: [\"About\", \"Blog\", \"Careers\", \"Contact\"] },\n];\nexport function FooterTemplate() {\n    return (<div className=\"bg-background px-8 pb-8 pt-14\">\n      <div className=\"mx-auto max-w-4xl\">\n        <div className=\"grid gap-10 @xl:grid-cols-[1.4fr_1fr_1fr_1fr]\">\n          <div>\n            <span className=\"flex items-center gap-2.5\">\n              <span className=\"flex h-7 w-7 items-center justify-center rounded-lg bg-foreground text-background\">\n                <Layers className=\"h-4 w-4\"/>\n              </span>\n              <span className=\"text-[15px] font-semibold tracking-[-0.01em]\">Nimbus</span>\n            </span>\n            <p className=\"mt-3.5 max-w-[220px] text-[13.5px] leading-relaxed text-muted-foreground\">\n              The open component library for teams that care about the\n              last 10 percent.\n            </p>\n          </div>\n          {footerColumns.map((column) => (<div key={column.heading}>\n              <p className=\"text-[13px] font-semibold text-foreground\">{column.heading}</p>\n              <ul className=\"mt-3 space-y-2\">\n                {column.links.map((link) => (<li key={link}>\n                    <Link href=\"#\" onClick={(e) => e.preventDefault()} className=\"text-[13.5px] text-muted-foreground transition-colors hover:text-foreground\">\n                      {link}\n                    </Link>\n                  </li>))}\n              </ul>\n            </div>))}\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-[var(--pollen-separator)] pt-6 @xl:flex-row\">\n          <p className=\"text-[12.5px] text-faint\">© 2026 Nimbus Labs. MIT licensed.</p>\n          <div className=\"flex items-center gap-2 text-[12.5px] text-faint\">\n            Press\n            <Kbd className=\"bg-fill\">⌘</Kbd>\n            <Kbd className=\"bg-fill\">K</Kbd>\n            to search\n          </div>\n        </div>\n      </div>\n    </div>);\n}\n"};

